  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 24 del Código Civil, la pérdida de la nacionalidad de los emancipados que, residiendo habitualmente en el extranjero, adquieran voluntariamente otra nacionalidad se producirá una vez transcurridos:', 'El art. 24.1 CC fija un plazo de tres años, dentro del cual el interesado puede evitar la pérdida declarando ante el encargado del Registro Civil su voluntad de conservar la nacionalidad española.', 'pn_01_derecho_persona', (select id from public.topics where slug = 'pn-01-derecho-persona'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Art. 24.1 CC', 'La pérdida se producirá una vez que transcurran tres años, a contar, respectivamente, desde la adquisición de la nacionalidad extranjera o desde la emancipación. No obstante, los interesados podrán evitar la pérdida si dentro del plazo indicado declaran su voluntad de conservar la nacionalidad española al encargado del Registro Civil.', null, 'a5afc52e87ff9117347cdefcea84e045c9983446d1072041a6b2a092667fbcff', false
