  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 55.1 de la Constitución, en el supuesto de declaración del estado de excepción no podrán suspenderse los derechos reconocidos en:', 'El art. 55.1 CE permite suspender en los estados de excepción y de sitio los derechos de los arts. 17, 18.2 y 3, 19, 20.1.a) y d) y 5, 21, 28.2 y 37.2, pero exceptúa el art. 17.3 en el estado de excepción.', 'pn_02_constitucion_1', (select id from public.topics where slug = 'pn-02-constitucion-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 55.1 CE', '1. Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución. Se exceptúa de lo establecido anteriormente el apartado 3 del artículo 17 para el supuesto de declaración de estado de excepción.', null, 'f2fdb959f2dacee72bb7d0858284af6951353959e85c9e0b1d95b2705eafea6c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f2fdb959f2dacee72bb7d0858284af6951353959e85c9e0b1d95b2705eafea6c')
