  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 55.2 de la Constitución, en relación con las investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas, una ley orgánica podrá determinar la suspensión individual de los derechos reconocidos en:', 'El art. 55.2 CE permite la suspensión individual, con intervención judicial y control parlamentario, de la duración de la detención (17.2), la inviolabilidad del domicilio (18.2) y el secreto de las comunicaciones (18.3).', 'pn_02_constitucion_1', (select id from public.topics where slug = 'pn-02-constitucion-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 55.2 CE', '2. Una ley orgánica podrá determinar la forma y los casos en los que, de forma individual y con la necesaria intervención judicial y el adecuado control parlamentario, los derechos reconocidos en los artículos 17, apartado 2, y 18, apartados 2 y 3, pueden ser suspendidos para personas determinadas, en relación con las investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas.', null, 'd8cad47be29d22ba0541b7d0bbd0be67b2243023c8527c8d47ffff2bfdf9c510', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd8cad47be29d22ba0541b7d0bbd0be67b2243023c8527c8d47ffff2bfdf9c510')
  returning id
), o as (
