  select 'Según la Ley Orgánica 3/1981, toda queja ante el Defensor del Pueblo deberá presentarse en el plazo máximo de:', 'El art. 15.Uno LODP exige queja firmada, con nombre, apellidos y domicilio, en escrito razonado y en el plazo máximo de un año desde el conocimiento de los hechos.', 'pn_02_constitucion_1', (select id from public.topics where slug = 'pn-02-constitucion-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 15.1 LODP', 'Uno. Toda queja se presentará firmada por el interesado, con indicación de su nombre, apellidos y domicilio, en escrito razonado en papel común y en el plazo máximo de un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.', null, '946948a0634291dd78ac8ba8ec17d937ebbcfe0e1849b4010800a81c1c45450c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '946948a0634291dd78ac8ba8ec17d937ebbcfe0e1849b4010800a81c1c45450c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seis meses, contados desde que se produjeron los hechos objeto de la misma.', false), ('B', 'Un año, contado a partir del momento en que el interesado tuviera conocimiento de los hechos objeto de la misma.', true), ('C', 'Tres meses, contados a partir del momento en que el interesado tuviera conocimiento de los hechos.', false)) as v(label, body, ok)
)
