  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 10 de la Ley Orgánica 3/1981, ¿quién no podrá presentar quejas ante el Defensor del Pueblo?', 'El art. 10 LODP permite acudir al Defensor del Pueblo a toda persona natural o jurídica con interés legítimo, sin que impidan hacerlo la minoría de edad o el internamiento penitenciario; solo excluye a las autoridades administrativas en asuntos de su competencia.', 'pn_02_constitucion_1', (select id from public.topics where slug = 'pn-02-constitucion-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 10.3 LODP', 'Tres. No podrá presentar quejas ante el Defensor del Pueblo ninguna autoridad administrativa en asuntos de su competencia.', null, '2f7429adf07c225e76cc9b53db42c908c79345e622aae67d2252d5fe8221519e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2f7429adf07c225e76cc9b53db42c908c79345e622aae67d2252d5fe8221519e')
