  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ninguna autoridad administrativa en asuntos de su competencia.', true), ('B', 'Las personas internadas en un centro penitenciario.', false), ('C', 'Los menores de edad que no estén emancipados.', false)) as v(label, body, ok)
)
