with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 del Tratado de la Unión Europea, ¿cuál de los siguientes órganos NO es una institución de la Unión?', 'El art. 13 TUE enumera siete instituciones (Parlamento Europeo, Consejo Europeo, Consejo, Comisión, TJUE, BCE y Tribunal de Cuentas); el Comité Económico y Social y el Comité de las Regiones son órganos consultivos.', 'pn_04_union_europea', (select id from public.topics where slug = 'pn-04-union-europea'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 13.1 TUE', 'Las instituciones de la Unión son: El Parlamento Europeo, El Consejo Europeo, El Consejo, La Comisión Europea (denominada en lo sucesivo «Comisión»), El Tribunal de Justicia de la Unión Europea, El Banco Central Europeo, El Tribunal de Cuentas. […] 4. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas.', null, 'cfbb355c4ef4e48c871b897afa8188494cf59c62c153cab2148000f6b28bc02e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cfbb355c4ef4e48c871b897afa8188494cf59c62c153cab2148000f6b28bc02e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Comité de las Regiones.', true), ('B', 'El Tribunal de Cuentas.', false), ('C', 'El Banco Central Europeo.', false)) as v(label, body, ok)
)
