with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 14 del Tratado de la Unión Europea, el número de diputados del Parlamento Europeo no excederá de:', 'El art. 14.2 TUE fija un máximo de 750 diputados más el Presidente, con representación decrecientemente proporcional, mínimo de seis y máximo de noventa y seis por Estado.', 'pn_04_union_europea', (select id from public.topics where slug = 'pn-04-union-europea'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 14.2 TUE', 'Su número no excederá de setecientos cincuenta, más el Presidente. La representación de los ciudadanos será decrecientemente proporcional, con un mínimo de seis diputados por Estado miembro. No se asignará a ningún Estado miembro más de noventa y seis escaños.', null, '0c5e9dffd96f1012bcdca153ebae1dc44c0bda8ddab9e8e1c03c8b41427dda3f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0c5e9dffd96f1012bcdca153ebae1dc44c0bda8ddab9e8e1c03c8b41427dda3f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Setecientos cincuenta, incluido el Presidente, con un mínimo de cuatro y un máximo de noventa y seis escaños por Estado miembro.', false), ('B', 'Setecientos cincuenta, más el Presidente, con un mínimo de seis y un máximo de noventa y seis escaños por Estado miembro.', true), ('C', 'Setecientos, más el Presidente, con un mínimo de seis y un máximo de cien escaños por Estado miembro.', false)) as v(label, body, ok)
)
