  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 50/1997, ¿cuál de las siguientes es una causa de cese del Gobierno?', 'El art. 21.1 de la Ley 50/1997 (como el art. 101.1 CE) fija como causas de cese la celebración de elecciones generales, la pérdida de la confianza parlamentaria y la dimisión o fallecimiento del Presidente.', 'pn_05_age_gobierno', (select id from public.topics where slug = 'pn-05-age-gobierno'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336'), 'Art. 21.1 LG', '1. El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente.', null, 'b9609dc5a892820f0202018d50b40b3af51f63487102e6e0a2223b866d2e5605', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b9609dc5a892820f0202018d50b40b3af51f63487102e6e0a2223b866d2e5605')
  returning id
), o as (
