  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La celebración de elecciones generales.', true), ('B', 'La dimisión de un Vicepresidente.', false), ('C', 'La aprobación de una moción de censura contra un Ministro.', false)) as v(label, body, ok)
)
