with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 50/1997, el Gobierno en funciones no podrá:', 'El art. 21.5 de la Ley 50/1997 impide al Gobierno en funciones aprobar el Proyecto de Ley de Presupuestos y presentar proyectos de ley; el art. 21.3 le obliga a limitar su gestión al despacho ordinario y le permite adoptar otras medidas en casos de urgencia o por razones de interés general debidamente acreditadas.', 'pn_05_age_gobierno', (select id from public.topics where slug = 'pn-05-age-gobierno'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336'), 'Art. 21.5 LG', 'limitará su gestión al despacho ordinario de los asuntos públicos, absteniéndose de adoptar, salvo casos de urgencia debidamente acreditados o por razones de interés general cuya acreditación expresa así lo justifique, cualesquiera otras medidas. […] 5. El Gobierno en funciones no podrá ejercer las siguientes facultades: a) Aprobar el Proyecto de Ley de Presupuestos Generales del Estado. b) Presentar proyectos de ley al Congreso de los Diputados o, en su caso, al Senado.', null, 'cead8be7790e32bb1f23f59dce434e89849cce663fda4a24fc11f94bb58a36b8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cead8be7790e32bb1f23f59dce434e89849cce663fda4a24fc11f94bb58a36b8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Limitar su gestión al despacho ordinario de los asuntos públicos.', false), ('B', 'Aprobar el Proyecto de Ley de Presupuestos Generales del Estado.', true), ('C', 'Adoptar medidas por razones de interés general cuya acreditación expresa así lo justifique.', false)) as v(label, body, ok)
)
