insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Señale la respuesta correcta sobre el personal eventual según el TREBEP:', 'El art. 12.3 TREBEP establece que el nombramiento y cese son libres y que el cese se produce en todo caso con el de la autoridad; el apartado 4 impide que esa condición sea mérito para el acceso o la promoción interna.', 'pn_06_funcionarios', (select id from public.topics where slug = 'pn-06-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 12.3-4 TREBEP', '3. El nombramiento y cese serán libres. El cese tendrá lugar, en todo caso, cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento. 4. La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna.', null, '503e77dce3eb9e74e1287ab96bc69060e0609eff07f5b2981a5542258d2b7584', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '503e77dce3eb9e74e1287ab96bc69060e0609eff07f5b2981a5542258d2b7584')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Su condición constituye mérito para el acceso a la Función Pública.', false), ('B', 'Su nombramiento exige superar un procedimiento que garantice la publicidad y la concurrencia.', false), ('C', 'Su cese tiene lugar, en todo caso, cuando se produce el de la autoridad a la que presta la función de confianza o asesoramiento.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
