with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el TREBEP, cuando el personal directivo profesional reúna la condición de personal laboral estará sometido a:', 'El art. 13.4 TREBEP somete al personal directivo laboral a la relación laboral especial de alta dirección y excluye sus condiciones de empleo de la negociación colectiva.', 'pn_06_funcionarios', (select id from public.topics where slug = 'pn-06-funcionarios'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 13.4 TREBEP', 'Cuando el personal directivo reúna la condición de personal laboral estará sometido a la relación laboral de carácter especial de alta dirección.', null, '8b76176b0ca663016bba7af6729a378ae33440b14f697cc8987f4b20d8a9b040', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8b76176b0ca663016bba7af6729a378ae33440b14f697cc8987f4b20d8a9b040')
