  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 63 del TREBEP, ¿cuál de las siguientes es causa de pérdida de la condición de funcionario de carrera?', 'El art. 63 TREBEP enumera como causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la separación del servicio firme y la pena firme de inhabilitación absoluta o especial para cargo público.', 'pn_06_funcionarios', (select id from public.topics where slug = 'pn-06-funcionarios'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 63 TREBEP', 'Son causas de pérdida de la condición de funcionario de carrera: a) La renuncia a la condición de funcionario. b) La pérdida de la nacionalidad. c) La jubilación total del funcionario. d) La sanción disciplinaria de separación del servicio que tuviere carácter firme. e) La pena principal o accesoria de inhabilitación absoluta o especial para cargo público que tuviere carácter firme.', null, 'b337f8ffbc59d8e8a2a1f7dc13e3da2a20c6e3b464a37182447987317341ac98', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b337f8ffbc59d8e8a2a1f7dc13e3da2a20c6e3b464a37182447987317341ac98')
  returning id
), o as (
