select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 67.3 del TREBEP, la prolongación de la permanencia en el servicio activo podrá solicitarse como máximo hasta que el funcionario cumpla:', 'El art. 67.3 TREBEP declara la jubilación forzosa de oficio a los sesenta y cinco años y permite solicitar la prolongación como máximo hasta los setenta, en los términos de las leyes de Función Pública; quedan excluidos los funcionarios con normas estatales específicas de jubilación.', 'pn_06_funcionarios', (select id from public.topics where slug = 'pn-06-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 67.3 TREBEP', 'No obstante, en los términos de las leyes de Función Pública que se dicten en desarrollo de este Estatuto, se podrá solicitar la prolongación de la permanencia en el servicio activo como máximo hasta que se cumpla setenta años de edad.', null, 'a46fbbe0c09763d2c1c3ee670d3ee00527c2a0ee2bc348bcf7b311cd1e198cbe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a46fbbe0c09763d2c1c3ee670d3ee00527c2a0ee2bc348bcf7b311cd1e198cbe')
