insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 207/2024, de 27 de febrero, estructura orgánica básica del Ministerio del Interior (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-07-ministerio-interior', 'Tema 7. El Ministerio del Interior y la Secretaría de Estado de Seguridad') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-07-ministerio-interior' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 207/2024, corresponde al Ministerio del Interior, entre otras competencias:', 'El art. 1.1 del RD 207/2024 atribuye al Ministerio el mando superior y la dirección y coordinación de las Fuerzas y Cuerpos de Seguridad del Estado; el mando directo corresponde a los Directores Generales de la Policía y de la Guardia Civil (arts. 3.1 y 4.1).', 'pn_07_ministerio_interior', (select id from public.topics where slug = 'pn-07-ministerio-interior'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793'), 'Art. 1.1 RD 207/2024', 'Corresponde al Ministerio del Interior la propuesta y ejecución de la política del Gobierno en materia de seguridad ciudadana; la promoción de las condiciones para el ejercicio de los derechos fundamentales, en particular, la libertad y seguridad personales, en los términos establecidos en la Constitución Española y en las leyes que los desarrollen; el mando superior y la dirección y coordinación de las Fuerzas y Cuerpos de Seguridad del Estado', null, '5c0ee943b4fcf4e96440c3b0c9480ccf860f628d3b51a5a85f59dc6e7d6f908d', false
