with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, de Régimen de Personal de la Policía Nacional, el mando directo de la Policía Nacional será ejercido por:', 'El art. 2.4 de la LO 9/2015 atribuye el mando superior al Ministro del Interior, a través del Secretario de Estado de Seguridad, y el mando directo al Director General de la Policía, bajo la autoridad del Secretario de Estado.', 'pn_08_policia_nacional', (select id from public.topics where slug = 'pn-08-policia-nacional'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Art. 2.4 LO 9/2015', '4. El mando superior de la Policía Nacional será ejercido por el Ministro del Interior, a través del Secretario de Estado de Seguridad. El mando directo será ejercido por el Director General de la Policía, bajo la autoridad del Secretario de Estado de Seguridad.', null, 'ea5993f5e79df3eb0dc397c1ccc83bb9dbe1c6148a7168450c30b0ee174220ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ea5993f5e79df3eb0dc397c1ccc83bb9dbe1c6148a7168450c30b0ee174220ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministro del Interior, a través del Secretario de Estado de Seguridad.', false), ('B', 'El Director General de la Policía, bajo la autoridad del Secretario de Estado de Seguridad.', true), ('C', 'El Director Adjunto Operativo, bajo la autoridad del Director General de la Policía.', false)) as v(label, body, ok)
)
