  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, la Policía Nacional es:', 'El art. 2.1 de la LO 9/2015 define a la Policía Nacional como instituto armado de naturaleza civil, con estructura jerarquizada y ámbito de actuación en todo el territorio nacional.', 'pn_08_policia_nacional', (select id from public.topics where slug = 'pn-08-policia-nacional'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Art. 2.1 LO 9/2015', '1. La Policía Nacional es un instituto armado de naturaleza civil, con estructura jerarquizada que tiene como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana, con ámbito de actuación en todo el territorio nacional.', null, 'e83f2204f8228f37ac6974f575064358f572c5d6c67d20ab5a86027b792ac0e1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e83f2204f8228f37ac6974f575064358f572c5d6c67d20ab5a86027b792ac0e1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un instituto armado de naturaleza civil, con estructura jerarquizada.', true), ('B', 'Un instituto armado de naturaleza militar, con estructura jerarquizada.', false), ('C', 'Un cuerpo de naturaleza civil no armado, con estructura jerarquizada.', false)) as v(label, body, ok)
)
