  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, el ingreso en la Policía Nacional por el procedimiento de oposición libre podrá efectuarse mediante el acceso a las categorías de:', 'El art. 25.1 de la LO 9/2015 prevé el ingreso por oposición libre en las categorías de Inspector y Policía, conforme a los principios de igualdad, mérito y capacidad.', 'pn_08_policia_nacional', (select id from public.topics where slug = 'pn-08-policia-nacional'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Art. 25.1 LO 9/2015', 'Dicho ingreso podrá efectuarse mediante el acceso a las categorías de Inspector y Policía, por el procedimiento de oposición libre, en los términos en que se determine reglamentariamente.', null, '35a0f73ac49a48ae361b7e86ebe681b0c39ed240400e1077486f6d775eadbd50', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '35a0f73ac49a48ae361b7e86ebe681b0c39ed240400e1077486f6d775eadbd50')
