insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-09-fuerzas-cuerpos-seguridad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad, la Seguridad Pública es:', 'El art. 1.1 de la LO 2/1986 declara la Seguridad Pública competencia exclusiva del Estado y atribuye su mantenimiento al Gobierno de la Nación; las Comunidades Autónomas y las Corporaciones Locales participan en ella (apartados 2 y 3).', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 1.1 LO 2/1986', '1. La Seguridad Pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación.', null, 'e087aec1874da278dd1d744a5acc4fa4c612036783132b0d1e3d8d0723ea700e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e087aec1874da278dd1d744a5acc4fa4c612036783132b0d1e3d8d0723ea700e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Competencia compartida entre el Estado y las Comunidades Autónomas, y su mantenimiento corresponde a ambos.', false), ('B', 'Competencia exclusiva del Estado, y su mantenimiento corresponde al Ministerio del Interior.', false), ('C', 'Competencia exclusiva del Estado, y su mantenimiento corresponde al Gobierno de la Nación.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley Orgánica 2/1986, ¿cuál de los siguientes NO es una Fuerza o Cuerpo de Seguridad?', 'El art. 2 de la LO 2/1986 enumera como Fuerzas y Cuerpos de Seguridad las del Estado, las policías de las Comunidades Autónomas y las de las Corporaciones Locales; el personal de seguridad privada tiene solo una especial obligación de auxiliarlas (art. 4.2).', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 2 LO 2/1986', 'Son Fuerzas y Cuerpos de Seguridad: a) Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación. b) Los Cuerpos de Policía dependientes de las Comunidades Autónomas. c) Los Cuerpos de Policía dependientes de las Corporaciones Locales.', null, '72bff8c1ba7cc9bb037afd97ac32ff443b41c4c6796946cc8ba741ce18b9d640', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '72bff8c1ba7cc9bb037afd97ac32ff443b41c4c6796946cc8ba741ce18b9d640')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los Cuerpos de Policía dependientes de las Corporaciones Locales.', false), ('B', 'El personal de seguridad privada.', true), ('C', 'Los Cuerpos de Policía dependientes de las Comunidades Autónomas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según los principios básicos de actuación de la Ley Orgánica 2/1986, los miembros de las Fuerzas y Cuerpos de Seguridad solamente deberán utilizar las armas en las situaciones en que exista:', 'El art. 5.2.d) de la LO 2/1986 limita el uso de las armas a situaciones de riesgo racionalmente grave para la vida o integridad propia o de terceros, o de grave riesgo para la seguridad ciudadana, conforme a los principios de congruencia, oportunidad y proporcionalidad.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 5.2.d) LO 2/1986', 'd) Solamente deberán utilizar las armas en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana y de conformidad con los principios a que se refiere el apartado anterior.', null, '9963467241d64274831cb3d9e5df9ea30f6e3a1eb89969999fb92d89bf76b5d0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9963467241d64274831cb3d9e5df9ea30f6e3a1eb89969999fb92d89bf76b5d0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas, o un grave riesgo para la seguridad ciudadana.', true), ('B', 'Un riesgo cierto para su vida o la de terceras personas, previa orden expresa de un superior jerárquico.', false), ('C', 'Cualquier resistencia activa a sus órdenes durante una detención.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, la obediencia debida de los miembros de las Fuerzas y Cuerpos de Seguridad:', 'El art. 5.1.d) de la LO 2/1986 sujeta la actuación a los principios de jerarquía y subordinación, pero excluye que la obediencia debida ampare órdenes manifiestamente delictivas o contrarias a la Constitución o a las Leyes.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 5.1.d) LO 2/1986', 'd) Sujetarse en su actuación profesional, a los principios de jerarquía y subordinación. En ningún caso, la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes.', null, '0c321b7c2ba61e492040be28b0888e028d47b1d0ac959c87ec2ba4a74f7b992d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0c321b7c2ba61e492040be28b0888e028d47b1d0ac959c87ec2ba4a74f7b992d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ampara cualquier orden de un superior, cuya responsabilidad asume quien la imparte.', false), ('B', 'Solo deja de amparar las órdenes que constituyan delito cuando así lo declare un juez.', false), ('C', 'En ningún caso podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
