with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, en el tratamiento de detenidos, los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales:', 'El art. 5.3.a) de la LO 2/1986 exige identificarse debidamente en el momento de efectuar la detención.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 5.3.a) LO 2/1986', 'a) Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales en el momento de efectuar una detención.', null, '628638c826725f24cec386bbb33744ee6061267952e65c36a84b0bee797f8ea4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '628638c826725f24cec386bbb33744ee6061267952e65c36a84b0bee797f8ea4')
