)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el principio de dedicación profesional de la Ley Orgánica 2/1986, los miembros de las Fuerzas y Cuerpos de Seguridad deberán intervenir en defensa de la Ley y de la seguridad ciudadana:', 'El art. 5.4 de la LO 2/1986 impone la total dedicación y la obligación de intervenir siempre, en cualquier tiempo y lugar, estén o no de servicio.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 5.4 LO 2/1986', 'Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana.', null, 'efebc796241adba9a2432ed1d73ca261ebc085b8c77d432d42e4f4e73c836ff6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'efebc796241adba9a2432ed1d73ca261ebc085b8c77d432d42e4f4e73c836ff6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre, en cualquier tiempo y lugar, se hallaren o no de servicio.', true), ('B', 'Solo mientras se hallen de servicio y dentro de su ámbito territorial.', false), ('C', 'Fuera de servicio, solo cuando sean requeridos por un ciudadano.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, el derecho de huelga de los miembros de las Fuerzas y Cuerpos de Seguridad:', 'El art. 6.8 de la LO 2/1986 prohíbe en todo caso la huelga y las acciones sustitutivas o concertadas para alterar el normal funcionamiento de los servicios.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 6.8 LO 2/1986', '8. Los miembros de las Fuerzas y Cuerpos de Seguridad no podrán ejercer en ningún caso el derecho de huelga, ni acciones sustitutivas del mismo o concertadas con el fin de alterar el normal funcionamiento de los servicios.', null, 'b0cf24478408277949fca32cf53074b25e7260fa866e4273db8430beebbdfe7e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b0cf24478408277949fca32cf53074b25e7260fa866e4273db8430beebbdfe7e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrá ejercerse garantizando los servicios mínimos.', false), ('B', 'No podrá ejercerse en ningún caso, ni tampoco acciones sustitutivas del mismo.', true), ('C', 'Podrá ejercerse previa autorización del Consejo de Policía.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, cuando se cometa delito de atentado contra miembros de las Fuerzas y Cuerpos de Seguridad empleando armas de fuego, explosivos u otros medios de agresión de análoga peligrosidad, estos tendrán, al efecto de su protección penal, la consideración de:', 'El art. 7 de la LO 2/1986 les da con carácter general el carácter de agentes de la autoridad (apartado 1), pero en el atentado con armas de fuego, explosivos o medios análogos tienen, a efectos de su protección penal, la consideración de autoridad (apartado 2).', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 7.2 LO 2/1986', '2. Cuando se cometa delito de atentado, empleando en su ejecución armas de fuego, explosivos u otros medios de agresión de análoga peligrosidad, que puedan poner en peligro grave la integridad física de los miembros de las Fuerzas y Cuerpos de Seguridad, tendrán al efecto de su protección penal la consideración de autoridad.', null, '7b1b096ba43fa43f62c37894421462dc73537e38fed5cb9a1514208a42773a23', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7b1b096ba43fa43f62c37894421462dc73537e38fed5cb9a1514208a42773a23')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Agentes de la autoridad.', false), ('B', 'Funcionarios públicos.', false), ('C', 'Autoridad.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
