with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1986, en tiempo de guerra y durante el estado de sitio, la Guardia Civil dependerá:', 'El art. 9.b) de la LO 2/1986 define la Guardia Civil como instituto armado de naturaleza militar que depende del Ministro del Interior y del de Defensa según sus funciones, y exclusivamente del Ministro de Defensa en tiempo de guerra y durante el estado de sitio.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 9.b) LO 2/1986', 'En tiempo de guerra y durante el estado de sitio, dependerá exclusivamente del Ministro de Defensa.', null, '6fd5d968557f603e384ad5550bec96544898fa3011e10a08f3726c52f2f99301', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6fd5d968557f603e384ad5550bec96544898fa3011e10a08f3726c52f2f99301')
  returning id
