with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, son organizaciones sindicales representativas de la Policía Nacional las que en las últimas elecciones al Consejo de Policía hubieran obtenido:', 'El art. 89.1 de la LO 9/2015 exige al menos un representante en el Consejo de Policía, o al menos el 10 % de los votos en cada una de dos escalas. Los derechos de representación colectiva de la LO 2/1986 (arts. 18 a 24) están derogados y hoy los regula la LO 9/2015.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Art. 89.1 LO 9/2015', '1. Aquellas organizaciones sindicales de la Policía Nacional que en las últimas elecciones al Consejo de Policía hubieran obtenido, al menos, un representante en dicho Consejo, o en dos de las escalas al menos el 10 % de los votos emitidos en cada una de ellas, serán consideradas organizaciones sindicales representativas', null, 'db065e95073fd3123f1a8d0a6ffcb2c02dd7d307a4b8e8112c1675eb5a4d8307', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'db065e95073fd3123f1a8d0a6ffcb2c02dd7d307a4b8e8112c1675eb5a4d8307')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al menos un representante en dicho Consejo, o en dos de las escalas al menos el 10 % de los votos emitidos en cada una de ellas.', true), ('B', 'Al menos dos representantes en dicho Consejo, o en una de las escalas al menos el 15 % de los votos emitidos.', false), ('C', 'Al menos un representante en dicho Consejo y el 10 % de los votos emitidos en el conjunto de las escalas.', false)) as v(label, body, ok)
)
