with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 9/2015, el Consejo de Policía es un órgano colegiado de participación:', 'El art. 94.1 de la LO 9/2015 configura el Consejo de Policía como órgano paritario presidido por el Ministro del Interior o persona en quien delegue. La regulación del Consejo en la LO 2/1986 (arts. 25 y 26) está derogada.', 'pn_09_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'pn-09-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-8468'), 'Art. 94.1 LO 9/2015', '1. Bajo la presidencia del Ministro del Interior o persona en quien delegue, existirá el Consejo de Policía, órgano colegiado de participación con representación paritaria de la Administración y de los representantes de los miembros de la Policía Nacional.', null, '8bbf8baded21871614216eb339c9872133a69a9a135bc61ad9d8aab8145ea0e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8bbf8baded21871614216eb339c9872133a69a9a135bc61ad9d8aab8145ea0e8')
