with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 12/2009, el derecho de asilo es la protección dispensada a los nacionales no comunitarios o a los apátridas a quienes se reconozca la condición de refugiado en los términos definidos en esa Ley y en la Convención sobre el Estatuto de los Refugiados hecha en:', 'El art. 2 de la Ley 12/2009 remite a la Convención de Ginebra de 28 de julio de 1951 y a su Protocolo de Nueva York de 31 de enero de 1967; la Convención de Nueva York de 1954 es la de los apátridas.', 'pn_12_proteccion_internacional', (select id from public.topics where slug = 'pn-12-proteccion-internacional'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242'), 'Art. 2 Ley 12/2009', 'El derecho de asilo es la protección dispensada a los nacionales no comunitarios o a los apátridas a quienes se reconozca la condición de refugiado en los términos definidos en el artículo 3 de esta Ley y en la Convención sobre el Estatuto de los Refugiados, hecha en Ginebra el 28 de julio de 1951', null, '76337021be6f25985bfff8b5ec62d56f45c2feee7f121860b13d77669c61bd42', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '76337021be6f25985bfff8b5ec62d56f45c2feee7f121860b13d77669c61bd42')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Nueva York el 28 de septiembre de 1954.', false), ('B', 'Ginebra el 28 de julio de 1951.', true), ('C', 'Roma el 4 de noviembre de 1950.', false)) as v(label, body, ok)
)
