with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 12/2009, ¿cuál de los siguientes es un motivo de persecución que permite reconocer la condición de refugiado?', 'El art. 3 de la Ley 12/2009 enumera como motivos la raza, la religión, la nacionalidad, las opiniones políticas, la pertenencia a determinado grupo social, de género, la orientación sexual o la identidad sexual; los motivos económicos no figuran.', 'pn_12_proteccion_internacional', (select id from public.topics where slug = 'pn-12-proteccion-internacional'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242'), 'Art. 3 Ley 12/2009', 'debido a fundados temores de ser perseguida por motivos de raza, religión, nacionalidad, opiniones políticas, pertenencia a determinado grupo social, de género, orientación sexual o de identidad sexual', null, 'c142c1ea5b55894af2f61ad57617547e1321f8bfeb8d7dc0f968eaf4ef0bf5c8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c142c1ea5b55894af2f61ad57617547e1321f8bfeb8d7dc0f968eaf4ef0bf5c8')
  returning id
), o as (
