  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La situación de pobreza en el país de origen.', false), ('B', 'La búsqueda de empleo en el extranjero.', false), ('C', 'La orientación sexual.', true)) as v(label, body, ok)
)
