with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 12/2009, el derecho a la protección subsidiaria se dispensa a las personas que, sin reunir los requisitos para ser reconocidas como refugiadas, si regresasen a su país de origen:', 'El art. 4 de la Ley 12/2009 vincula la protección subsidiaria al riesgo real de sufrir los daños graves del art. 10 (pena de muerte, tortura o tratos inhumanos, amenazas graves por violencia indiscriminada).', 'pn_12_proteccion_internacional', (select id from public.topics where slug = 'pn-12-proteccion-internacional'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-17242'), 'Art. 4 Ley 12/2009', 'se enfrentarían a un riesgo real de sufrir alguno de los daños graves previstos en el artículo 10 de esta Ley', null, '466070bb85042a29721e5b7205c4f2393269f30b4bcdd1e4216b87f47af3a0d1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '466070bb85042a29721e5b7205c4f2393269f30b4bcdd1e4216b87f47af3a0d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se enfrentarían a un riesgo real de sufrir alguno de los daños graves previstos en la Ley.', true), ('B', 'Se encontrarían en una situación de desempleo o carencia de medios de vida.', false), ('C', 'No podrían reagruparse con los miembros de su familia.', false)) as v(label, body, ok)
)
