  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 5/2014, las empresas de seguridad, los despachos de detectives y el personal de seguridad privada deberán comunicar a las Fuerzas y Cuerpos de Seguridad competentes los hechos delictivos de los que tuviesen conocimiento en el ejercicio de su actividad:', 'El art. 14.2 de la Ley 5/2014 impone comunicar tan pronto como sea posible las informaciones relevantes para la seguridad ciudadana y todo hecho delictivo conocido, con entrega de presuntos delincuentes, instrumentos, efectos y pruebas.', 'pn_13_seguridad_privada', (select id from public.topics where slug = 'pn-13-seguridad-privada'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Art. 14.2 Ley 5/2014', '2. Las empresas de seguridad, los despachos de detectives y el personal de seguridad privada deberán comunicar a las Fuerzas y Cuerpos de Seguridad competentes, tan pronto como sea posible, cualesquiera circunstancias o informaciones relevantes para la prevención, el mantenimiento o restablecimiento de la seguridad ciudadana, así como todo hecho delictivo del que tuviesen conocimiento en el ejercicio de su actividad o funciones, poniendo a su disposición a los presuntos delincuentes, así como los instrumentos, efectos y pruebas relacionadas con los mismos.', null, '291de50deda12ae456d571d70e784f176f5acbb44dde753fdfefd226a2342b3a', false
