  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 5/2014, al efectuar controles de identidad en el acceso a los inmuebles donde presten servicio, los vigilantes de seguridad:', 'El art. 32.1.b) de la Ley 5/2014 prohíbe retener la documentación personal; la negativa a identificarse faculta para impedir el acceso o para ordenar el abandono del inmueble.', 'pn_13_seguridad_privada', (select id from public.topics where slug = 'pn-13-seguridad-privada'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Art. 32.1.b) Ley 5/2014', 'b) Efectuar controles de identidad, de objetos personales, paquetería, mercancías o vehículos, incluido el interior de éstos, en el acceso o en el interior de inmuebles o propiedades donde presten servicio, sin que, en ningún caso, puedan retener la documentación personal, pero sí impedir el acceso a dichos inmuebles o propiedades.', null, 'b5aa1d810ca6a4b305cc71154ff366e90f18916f1179bb64adb8b8f4dc49d7a6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b5aa1d810ca6a4b305cc71154ff366e90f18916f1179bb64adb8b8f4dc49d7a6')
  returning id
), o as (
