  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En ningún caso pueden retener la documentación personal, pero sí impedir el acceso.', true), ('B', 'Pueden retener la documentación personal mientras la persona permanezca en el inmueble.', false), ('C', 'Pueden retener la documentación personal solo si la persona se niega a someterse al control.', false)) as v(label, body, ok)
