  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 5/2014, ¿cuál de los siguientes servicios de seguridad privada se prestará con armas de fuego, en los términos que reglamentariamente se determinen?', 'El art. 40.1 de la Ley 5/2014 enumera los servicios con armas de fuego: transporte y custodia de fondos y valores, fábricas y depósitos de armas y explosivos, buques en aguas de grave riesgo y, cuando lo requieran, protección perimetral de centros penitenciarios, CIE, establecimientos militares y otros edificios públicos.', 'pn_13_seguridad_privada', (select id from public.topics where slug = 'pn-13-seguridad-privada'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649'), 'Art. 40.1 Ley 5/2014', '1. Los siguientes servicios de seguridad privada se prestarán con armas de fuego en los términos que reglamentariamente se determinen: a) Los de vigilancia y protección del almacenamiento, recuento, clasificación y transporte de dinero, valores y objetos valiosos.', null, '86c2eed8a9bf60b3b577da297fcfd4de53a2ae4fd46c938292f63c5f707115ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '86c2eed8a9bf60b3b577da297fcfd4de53a2ae4fd46c938292f63c5f707115ce')
  returning id
