with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 4/2015, de protección de la seguridad ciudadana, la salvaguarda de la seguridad ciudadana, como bien jurídico de carácter colectivo, es función:', 'El art. 1.1 LO 4/2015 configura la seguridad ciudadana como requisito indispensable para el ejercicio de los derechos fundamentales y atribuye su salvaguarda al Estado.', 'pn_14_seguridad_ciudadana', (select id from public.topics where slug = 'pn-14-seguridad-ciudadana'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'Art. 1.1 LOPSC', '1. La seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes.', null, '344475afa37ddf2d63cb1d72634a92bf6dc21f78be69b5f4665220499579e3c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '344475afa37ddf2d63cb1d72634a92bf6dc21f78be69b5f4665220499579e3c5')
  returning id
), o as (
