  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De las comunidades autónomas, con sujeción a sus estatutos de autonomía.', false), ('B', 'Del Estado, con sujeción a la Constitución y a las Leyes.', true), ('C', 'De los municipios, con sujeción a la legislación de régimen local.', false)) as v(label, body, ok)
)
