insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-15-infraestructuras-criticas' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 8/2011, las infraestructuras estratégicas cuyo funcionamiento es indispensable y no permite soluciones alternativas, por lo que su perturbación o destrucción tendría un grave impacto sobre los servicios esenciales, son:', 'El art. 2.e) de la Ley 8/2011 define las infraestructuras críticas como las estratégicas indispensables y sin soluciones alternativas cuya perturbación o destrucción tendría un grave impacto sobre los servicios esenciales.', 'pn_15_infraestructuras_criticas', (select id from public.topics where slug = 'pn-15-infraestructuras-criticas'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-7630'), 'Art. 2.e) Ley 8/2011', 'e) Infraestructuras críticas: las infraestructuras estratégicas cuyo funcionamiento es indispensable y no permite soluciones alternativas, por lo que su perturbación o destrucción tendría un grave impacto sobre los servicios esenciales.', null, '9def9b19f5f73f715a41421b70ed4afc2f92bcd23effe8c0e31118aa26989656', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9def9b19f5f73f715a41421b70ed4afc2f92bcd23effe8c0e31118aa26989656')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Infraestructuras críticas.', true), ('B', 'Infraestructuras estratégicas de primer nivel.', false), ('C', 'Zonas críticas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
