  select 'Según la Ley 8/2011, son infraestructuras críticas europeas aquellas situadas en algún Estado miembro de la Unión Europea cuya perturbación o destrucción afectaría gravemente:', 'El art. 2.f) de la Ley 8/2011 exige que la perturbación o destrucción afecte gravemente al menos a dos Estados miembros.', 'pn_15_infraestructuras_criticas', (select id from public.topics where slug = 'pn-15-infraestructuras-criticas'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-7630'), 'Art. 2.f) Ley 8/2011', 'f) Infraestructuras críticas europeas: aquellas infraestructuras críticas situadas en algún Estado miembro de la Unión Europea, cuya perturbación o destrucción afectaría gravemente al menos a dos Estados miembros', null, '2165d96458a7af93fde0630cb49de1864be605395da5f3be8774225efbdb33d5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2165d96458a7af93fde0630cb49de1864be605395da5f3be8774225efbdb33d5')
