insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 8/2011, ¿qué órgano es competente para designar a los operadores críticos?', 'El art. 11.2 de la Ley 8/2011 atribuye a la Comisión la aprobación de los Planes Estratégicos Sectoriales y la designación de los operadores críticos, a propuesta del Grupo de Trabajo Interdepartamental.', 'pn_15_infraestructuras_criticas', (select id from public.topics where slug = 'pn-15-infraestructuras-criticas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-7630'), 'Art. 11.2 Ley 8/2011', '2. La Comisión será la competente para aprobar los diferentes Planes Estratégicos Sectoriales así como para designar a los operadores críticos, a propuesta del Grupo de Trabajo Interdepartamental para la Protección de Infraestructuras Críticas.', null, 'b04329c421daa903403d3e3831d5bbb6f2474eba211d30b5abdf90f633538eb5', false
