insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 8/2011, los Planes de Apoyo Operativo deberán ser elaborados:', 'El art. 14.5 de la Ley 8/2011 atribuye los Planes de Apoyo Operativo al Cuerpo Policial estatal o autonómico competente en la demarcación, para cada infraestructura crítica dotada de Plan de Protección Específico.', 'pn_15_infraestructuras_criticas', (select id from public.topics where slug = 'pn-15-infraestructuras-criticas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-7630'), 'Art. 14.5 Ley 8/2011', '5. Los Planes de Apoyo Operativo deberán ser elaborados por el Cuerpo Policial estatal o, en su caso, autonómico, con competencia en la demarcación, para cada una de las infraestructuras clasificadas como Críticas o Críticas Europeas dotadas de un Plan de Protección Específico', null, '73ea6641a1872ac8d327f90b3133628ae88f55933a387dfb68fb3df27660b385', false
