with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 8/2011, ¿qué requisito es necesario para la designación de un operador crítico?', 'El art. 13.2 de la Ley 8/2011 exige que al menos una de las infraestructuras gestionadas sea Infraestructura Crítica; el CNPIC informará al operador antes de la clasificación definitiva.', 'pn_15_infraestructuras_criticas', (select id from public.topics where slug = 'pn-15-infraestructuras-criticas'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-7630'), 'Art. 13.2 Ley 8/2011', '2. Será requisito para la designación de los operadores críticos, tanto del sector público como del privado, que al menos una de las infraestructuras que gestionen reúna la consideración de Infraestructura Crítica', null, 'd2545afc6cb45d0f4ae0d67343e7e4fcece4cf61a3f3803a824976dd5b9e323f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd2545afc6cb45d0f4ae0d67343e7e4fcece4cf61a3f3803a824976dd5b9e323f')
  returning id
), o as (
