  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, el que causara a otro la pérdida o la inutilidad de un órgano o miembro principal, o de un sentido, será castigado con la pena de prisión de:', 'El art. 149.1 CP castiga con prisión de seis a doce años la pérdida o inutilidad de un órgano o miembro principal o de un sentido; la de un órgano o miembro no principal se castiga con prisión de tres a seis años (art. 150).', 'pn_17_penal_personas', (select id from public.topics where slug = 'pn-17-penal-personas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 149.1 CP', '1. El que causara a otro, por cualquier medio o procedimiento, la pérdida o la inutilidad de un órgano o miembro principal, o de un sentido, la impotencia, la esterilidad, una grave deformidad, o una grave enfermedad somática o psíquica, será castigado con la pena de prisión de seis a 12 años.', null, 'aa879a08606b7040ce136589061996ef8c9c7e4f39764dd30d3dd65d5b675978', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'aa879a08606b7040ce136589061996ef8c9c7e4f39764dd30d3dd65d5b675978')
