with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, el que acose a una persona llevando a cabo de forma insistente y reiterada, sin estar legítimamente autorizado, alguna de las conductas previstas (como vigilarla, perseguirla o buscar su cercanía física) y altere así el normal desarrollo de su vida cotidiana, será castigado con:', 'El art. 172 ter.1 CP castiga el acoso con prisión de tres meses a dos años o multa de seis a veinticuatro meses; con carácter general solo es perseguible mediante denuncia (art. 172 ter.4).', 'pn_17_penal_personas', (select id from public.topics where slug = 'pn-17-penal-personas'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 172 ter.1 CP', '1. Será castigado con la pena de prisión de tres meses a dos años o multa de seis a veinticuatro meses el que acose a una persona llevando a cabo de forma insistente y reiterada, y sin estar legítimamente autorizado, alguna de las conductas siguientes y, de esta forma, altere el normal desarrollo de su vida cotidiana: 1.ª La vigile, la persiga o busque su cercanía física.', null, 'b8101ea0548909ad3e4058ec2f81eea885ccfd89cf0932a279712bbcada02afe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b8101ea0548909ad3e4058ec2f81eea885ccfd89cf0932a279712bbcada02afe')
