with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 178 del Código Penal, a efectos del delito de agresión sexual, solo se entenderá que hay consentimiento cuando:', 'El art. 178.1 CP define el consentimiento como el manifestado libremente mediante actos que expresen de manera clara la voluntad de la persona; la agresión sexual básica se castiga con prisión de uno a cuatro años.', 'pn_17_penal_personas', (select id from public.topics where slug = 'pn-17-penal-personas'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 178.1 CP', 'Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona.', null, 'c41cd40b6d4616c50687974a227fe92fd4f5cea09701ad868ec2a0908908ecd5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c41cd40b6d4616c50687974a227fe92fd4f5cea09701ad868ec2a0908908ecd5')
