insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-18-penal-patrimonio', 'Tema 18. Delitos contra el patrimonio y el orden socioeconómico') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-18-penal-patrimonio' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, el que, con ánimo de lucro, tomare las cosas muebles ajenas sin la voluntad de su dueño será castigado, como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de:', 'El art. 234.1 CP fija en 400 euros el umbral del hurto castigado con prisión de seis a dieciocho meses; por debajo se impone multa de uno a tres meses (art. 234.2).', 'pn_18_penal_patrimonio', (select id from public.topics where slug = 'pn-18-penal-patrimonio'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 234.1 CP', '1. El que, con ánimo de lucro, tomare las cosas muebles ajenas sin la voluntad de su dueño será castigado, como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros.', null, '30db45854451de21fa1956f4e1c27fca1fce0abea2b7420325a78b4bb368da8b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '30db45854451de21fa1956f4e1c27fca1fce0abea2b7420325a78b4bb368da8b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '1.000 euros.', false), ('B', '50.000 euros.', false), ('C', '400 euros.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 234 del Código Penal, aunque la cuantía de lo sustraído no exceda de 400 euros, se impondrá la pena de prisión de seis a dieciocho meses cuando el culpable hubiera sido condenado ejecutoriamente:', 'El art. 234.2 CP castiga el hurto de hasta 400 euros con multa de uno a tres meses, pero impone la pena del apartado 1 si el culpable tiene al menos tres condenas ejecutorias por delitos de la misma naturaleza de este Título y al menos una es leve; no se computan los antecedentes cancelados.', 'pn_18_penal_patrimonio', (select id from public.topics where slug = 'pn-18-penal-patrimonio'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 234.2 CP', 'No obstante, en el caso de que el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de la misma naturaleza, comprendidos en este Título, y siendo al menos uno de ellos leve, se impondrá la pena prevista en el apartado 1 de este artículo.', 'El art. 234.2 CP ha sido modificado por la Ley Orgánica 1/2026, de 8 de abril (multirreincidencia). Comprobar que la redacción citada es la vigente y su fecha de entrada en vigor.', '6a83cacb8ff130db42c19b82e37f0b506621b176f5a63fe6470032e222e8f66c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6a83cacb8ff130db42c19b82e37f0b506621b176f5a63fe6470032e222e8f66c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
