with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 249 del Código Penal, los que, utilizando de forma fraudulenta tarjetas de crédito o débito o cualquier otro instrumento de pago distinto del efectivo, realicen operaciones de cualquier clase en perjuicio de su titular o de un tercero:', 'El art. 249.1.b) CP considera estafa el uso fraudulento de tarjetas y otros instrumentos de pago distintos del efectivo, castigado con prisión de seis meses a tres años.', 'pn_18_penal_patrimonio', (select id from public.topics where slug = 'pn-18-penal-patrimonio'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 249.1.b) CP', '1. También se consideran reos de estafa y serán castigados con la pena de prisión de seis meses a tres años: […] b) Los que, utilizando de forma fraudulenta tarjetas de crédito o débito, cheques de viaje o cualquier otro instrumento de pago material o inmaterial distinto del efectivo o los datos obrantes en cualquiera de ellos, realicen operaciones de cualquier clase en perjuicio de su titular o de un tercero.', null, 'f69985f62b1e39c61c6d357e9fab981aba9351973a4eaa9785a7c68346d472ac', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f69985f62b1e39c61c6d357e9fab981aba9351973a4eaa9785a7c68346d472ac')
  returning id
), o as (
