with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 250 del Código Penal, el delito de estafa será castigado con las penas de prisión de uno a seis años y multa de seis a doce meses, entre otros casos, cuando el valor de la defraudación supere:', 'El art. 250.1.5.º CP agrava la estafa cuando lo defraudado supera los 50.000 euros o afecta a un elevado número de personas; por encima de 250.000 euros la pena sube a prisión de cuatro a ocho años (art. 250.2).', 'pn_18_penal_patrimonio', (select id from public.topics where slug = 'pn-18-penal-patrimonio'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 250.1.5.º CP', '5.º El valor de la defraudación supere los 50.000 euros, o afecte a un elevado número de personas.', null, 'fae07b603021f24ee8edd07b194cfab37b826bab3454afb7181b7a23f2c3cd20', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fae07b603021f24ee8edd07b194cfab37b826bab3454afb7181b7a23f2c3cd20')
  returning id
), o as (
