with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código Penal, los que, en perjuicio de otro, se apropiaren para sí o para un tercero de dinero, efectos, valores o cualquier otra cosa mueble que hubieran recibido en depósito, comisión o custodia, o negaren haberlos recibido, cometen un delito de:', 'El art. 253.1 CP tipifica la apropiación indebida y la castiga con las penas de la estafa (arts. 248 o 250), salvo que ya esté castigada con pena más grave en otro precepto.', 'pn_18_penal_patrimonio', (select id from public.topics where slug = 'pn-18-penal-patrimonio'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 253.1 CP', '1. Serán castigados con las penas del artículo 248 o, en su caso, del artículo 250, salvo que ya estuvieran castigados con una pena más grave en otro precepto de este Código, los que, en perjuicio de otro, se apropiaren para sí o para un tercero, de dinero, efectos, valores o cualquier otra cosa mueble, que hubieran recibido en depósito, comisión, o custodia, o que les hubieran sido confiados en virtud de cualquier otro título que produzca la obligación de entregarlos o devolverlos, o negaren haberlos recibido.', null, '9d54445a30f3d8e485cbe4546bdcc56a9b78bb67575170bfab7931d568a188bf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d54445a30f3d8e485cbe4546bdcc56a9b78bb67575170bfab7931d568a188bf')
  returning id
