insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-20-delitos-informaticos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 197.1 del Código Penal, quien, para descubrir los secretos o vulnerar la intimidad de otro, sin su consentimiento, se apodere de sus mensajes de correo electrónico será castigado con:', 'El art. 197.1 CP castiga el apoderamiento de papeles, cartas, correos electrónicos u otros documentos, y la interceptación de telecomunicaciones, con prisión de uno a cuatro años y multa de doce a veinticuatro meses.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197.1 CP', 'El que, para descubrir los secretos o vulnerar la intimidad de otro, sin su consentimiento, se apodere de sus papeles, cartas, mensajes de correo electrónico o cualesquiera otros documentos o efectos personales, intercepte sus telecomunicaciones o utilice artificios técnicos de escucha, transmisión, grabación o reproducción del sonido o de la imagen, o de cualquier otra señal de comunicación, será castigado con las penas de prisión de uno a cuatro años y multa de doce a veinticuatro meses.', null, '3c14ba011ad4949931ff164db4a73fbf3b8b95bc4263fbf111df2f74d5d939a0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3c14ba011ad4949931ff164db4a73fbf3b8b95bc4263fbf111df2f74d5d939a0')
  returning id
), o as (
