)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 197.3 del Código Penal, si se difunden, revelan o ceden a terceros los datos o hechos descubiertos o las imágenes captadas, se impondrá la pena de:', 'El art. 197.3 CP castiga con prisión de dos a cinco años la difusión, revelación o cesión a terceros de lo descubierto; a quien lo difunda sin haber participado en el descubrimiento, conociendo su origen ilícito, se le impone prisión de uno a tres años y multa.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197.3 CP', 'Se impondrá la pena de prisión de dos a cinco años si se difunden, revelan o ceden a terceros los datos o hechos descubiertos o las imágenes captadas a que se refieren los números anteriores.', null, '51eba1413c3a4024baf427d2086f1752c99342cdf6836d4ad81fe75b77ee4253', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '51eba1413c3a4024baf427d2086f1752c99342cdf6836d4ad81fe75b77ee4253')
