with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 197.7 del Código Penal, quien, sin autorización de la persona afectada, difunda imágenes de aquella que hubiera obtenido con su anuencia en un domicilio, cuando la divulgación menoscabe gravemente su intimidad personal, será castigado con:', 'El art. 197.7 CP castiga esta difusión con prisión de tres meses a un año o multa de seis a doce meses; a quien, habiendo recibido esas imágenes, las difunda, se le impone multa de uno a tres meses.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197.7 CP', 'Será castigado con una pena de prisión de tres meses a un año o multa de seis a doce meses el que, sin autorización de la persona afectada, difunda, revele o ceda a terceros imágenes o grabaciones audiovisuales de aquélla que hubiera obtenido con su anuencia en un domicilio o en cualquier otro lugar fuera del alcance de la mirada de terceros, cuando la divulgación menoscabe gravemente la intimidad personal de esa persona.', null, 'c862405e472cc39362565c2e7d2760886f02c349cf2fe4cdc44e1773d730553c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c862405e472cc39362565c2e7d2760886f02c349cf2fe4cdc44e1773d730553c')
