with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 249 del Código Penal, también se consideran reos de estafa los que, con ánimo de lucro, valiéndose de alguna manipulación informática o artificio semejante:', 'El art. 249.1.a) CP tipifica la estafa informática: lograr, con ánimo de lucro y mediante manipulación informática, una transferencia no consentida de un activo patrimonial en perjuicio de otro. El acceso ilícito (art. 197 bis) y los daños informáticos (art. 264) son delitos distintos.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 249.1 CP', 'Los que, con ánimo de lucro, obstaculizando o interfiriendo indebidamente en el funcionamiento de un sistema de información o introduciendo, alterando, borrando, transmitiendo o suprimiendo indebidamente datos informáticos o valiéndose de cualquier otra manipulación informática o artificio semejante, consigan una transferencia no consentida de cualquier activo patrimonial en perjuicio de otro.', null, 'dc6dc0eb962042e864fd650facec5b482c9059e021cdd0317b0927d991636851', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dc6dc0eb962042e864fd650facec5b482c9059e021cdd0317b0927d991636851')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Accedan sin autorización a un sistema de información, aunque no causen perjuicio patrimonial.', false), ('B', 'Borren o hagan inaccesibles datos informáticos ajenos.', false), ('C', 'Consigan una transferencia no consentida de cualquier activo patrimonial en perjuicio de otro.', true)) as v(label, body, ok)
)
