with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 264 del Código Penal, quien por cualquier medio, sin autorización y de manera grave, borrase o hiciese inaccesibles datos informáticos ajenos, cuando el resultado producido fuera grave, será castigado con:', 'El tipo básico de daños informáticos del art. 264.1 CP se castiga con prisión de seis meses a tres años.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 264.1 CP', 'El que por cualquier medio, sin autorización y de manera grave borrase, dañase, deteriorase, alterase, suprimiese o hiciese inaccesibles datos informáticos, programas informáticos o documentos electrónicos ajenos, cuando el resultado producido fuera grave, será castigado con la pena de prisión de seis meses a tres años.', null, 'f6cdb56549d93d8fbebeb0d73363382a543b2293a05397d4e0a724e7bf4b3d6a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f6cdb56549d93d8fbebeb0d73363382a543b2293a05397d4e0a724e7bf4b3d6a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Prisión de seis meses a tres años.', true), ('B', 'Prisión de seis meses a dos años o multa de tres a dieciocho meses.', false), ('C', 'Prisión de tres a ocho años y multa del triplo al décuplo del perjuicio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 264.2 del Código Penal, cuando los daños informáticos hayan afectado al sistema informático de una infraestructura crítica, se impondrá una pena de:', 'El art. 264.2 CP eleva la pena a prisión de dos a cinco años y multa del tanto al décuplo del perjuicio cuando concurre alguna de sus circunstancias, entre ellas la afectación a una infraestructura crítica (4.ª).', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 264.2 CP', 'Se impondrá una pena de prisión de dos a cinco años y multa del tanto al décuplo del perjuicio ocasionado, cuando en las conductas descritas concurra alguna de las siguientes circunstancias: […] 4.ª Los hechos hayan afectado al sistema informático de una infraestructura crítica', null, '6ae70bf7e58077a703fe920e9caf08ddc6140cf0193dc1fe1228de8a1eaa0b0d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6ae70bf7e58077a703fe920e9caf08ddc6140cf0193dc1fe1228de8a1eaa0b0d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Prisión de dos a cinco años y multa del tanto al décuplo del perjuicio ocasionado.', true), ('B', 'Prisión de seis meses a tres años.', false), ('C', 'Prisión de uno a cuatro años y multa de doce a veinticuatro meses.', false)) as v(label, body, ok)
)
