insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto de 14 de septiembre de 1882, Ley de Enjuiciamiento Criminal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-20-delitos-informaticos', 'Tema 20. Delitos informáticos, intimidad y prueba digital') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-20-delitos-informaticos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 588 bis a de la Ley de Enjuiciamiento Criminal, el principio de especialidad de las medidas de investigación tecnológica exige que la medida:', 'El art. 588 bis a.2 LECrim define la especialidad como la relación de la medida con un delito concreto; la ausencia de medidas menos gravosas corresponde a los principios de excepcionalidad y necesidad, y la delimitación por su utilidad, al de idoneidad.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 588 bis a.2 LECRIM', 'El principio de especialidad exige que una medida esté relacionada con la investigación de un delito concreto. No podrán autorizarse medidas de investigación tecnológica que tengan por objeto prevenir o descubrir delitos o despejar sospechas sin base objetiva.', null, '1dada693128e1fd4695338682d304ae254c8791483b7a69e5ef29f2b893197a1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1dada693128e1fd4695338682d304ae254c8791483b7a69e5ef29f2b893197a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se acuerde solo cuando no existan otras medidas menos gravosas e igualmente útiles.', false), ('B', 'Esté relacionada con la investigación de un delito concreto.', true), ('C', 'Tenga la duración imprescindible según su utilidad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
