with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, la resolución del juez de instrucción que autorice o deniegue una medida de investigación tecnológica se dictará en el plazo máximo de:', 'El art. 588 bis c.1 LECrim exige auto motivado, oído el Ministerio Fiscal, en el plazo máximo de veinticuatro horas.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 588 bis c.1 LECRIM', 'El juez de instrucción autorizará o denegará la medida solicitada mediante auto motivado, oído el Ministerio Fiscal. Esta resolución se dictará en el plazo máximo de veinticuatro horas desde que se presente la solicitud.', null, 'ef4a5cafbdf3efc7a0bddccc5df7a5832d0861e07c9d2abd0edc6618ae1fede7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ef4a5cafbdf3efc7a0bddccc5df7a5832d0861e07c9d2abd0edc6618ae1fede7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Setenta y dos horas desde que se presente la solicitud.', false), ('B', 'Dos días desde que se presente la solicitud.', false), ('C', 'Veinticuatro horas desde que se presente la solicitud.', true)) as v(label, body, ok)
)
