with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, la duración máxima inicial de la interceptación de las comunicaciones telefónicas y telemáticas es de:', 'El art. 588 ter g LECrim fija tres meses iniciales, prorrogables por periodos iguales hasta un máximo de dieciocho meses, computados desde la autorización judicial.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 588 ter g LECRIM', 'La duración máxima inicial de la intervención, que se computará desde la fecha de autorización judicial, será de tres meses, prorrogables por períodos sucesivos de igual duración hasta el plazo máximo de dieciocho meses.', null, '7b89a8b3846dd900e09e8d2daa9225775b09fd7ddc5e79a1be89606076fc8883', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7b89a8b3846dd900e09e8d2daa9225775b09fd7ddc5e79a1be89606076fc8883')
  returning id
