with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, la simple incautación de un ordenador durante un registro domiciliario:', 'El art. 588 sexies a.2 LECrim separa la incautación del dispositivo del acceso a su contenido, que requiere autorización judicial.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 588 sexies a.2 LECRIM', 'La simple incautación de cualquiera de los dispositivos a los que se refiere el apartado anterior, practicada durante el transcurso de la diligencia de registro domiciliario, no legitima el acceso a su contenido, sin perjuicio de que dicho acceso pueda ser autorizado ulteriormente por el juez competente.', null, 'd6c67af3c8bb31aeda2fd90b84fb5fecb2109013cd281997ba33519b53c77ca2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd6c67af3c8bb31aeda2fd90b84fb5fecb2109013cd281997ba33519b53c77ca2')
  returning id
), o as (
