  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No legitima el acceso a su contenido, sin perjuicio de que pueda ser autorizado ulteriormente por el juez competente.', true), ('B', 'Legitima el acceso a su contenido por los agentes que practican el registro.', false), ('C', 'Legitima el acceso a su contenido si lo autoriza el Ministerio Fiscal.', false)) as v(label, body, ok)
)
