with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, cuando en casos de urgencia la Policía Judicial examine directamente los datos de un dispositivo incautado, deberá comunicarlo al juez competente por escrito motivado inmediatamente y, en todo caso, dentro del plazo máximo de:', 'El art. 588 sexies c.4 LECrim exige comunicarlo dentro de las veinticuatro horas; el juez revoca o confirma la actuación en un máximo de 72 horas desde que fue ordenada la medida.', 'pn_20_delitos_informaticos', (select id from public.topics where slug = 'pn-20-delitos-informaticos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 588 sexies c.4 LECRIM', 'la Policía Judicial podrá llevar a cabo el examen directo de los datos contenidos en el dispositivo incautado, comunicándolo inmediatamente, y en todo caso dentro del plazo máximo de veinticuatro horas, por escrito motivado al juez competente', null, 'd9561ddea3f07f60b3fb7f3b6fc940435775b8444030068554357b3ef129c7e6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd9561ddea3f07f60b3fb7f3b6fc940435775b8444030068554357b3ef129c7e6')
  returning id
), o as (
