insert into public.sources (title, url, kind, publisher, published_on) values ('Constitución Española (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-21-procesal-penal', 'Tema 21. Derecho Procesal Penal: jurisdicción, denuncia, detención, habeas corpus, Ministerio Fiscal y Policía Judicial') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-21-procesal-penal' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 126 de la Constitución, la policía judicial, en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, depende:', 'El art. 126 CE establece la dependencia funcional de la policía judicial respecto de Jueces, Tribunales y Ministerio Fiscal, en los términos que la ley establezca.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 126 CE', 'La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca.', null, '91144cbcc6b5f7e490d09ca2b6255834df3f7aa4b52e5ce7ea4bb91dff851752', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '91144cbcc6b5f7e490d09ca2b6255834df3f7aa4b52e5ce7ea4bb91dff851752')
