insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-21-procesal-penal' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del Estatuto Orgánico del Ministerio Fiscal, corresponde al Ministerio Fiscal intervenir en el proceso penal y, en el ámbito de la Ley Orgánica reguladora de la Responsabilidad Penal de los Menores:', 'El art. 3.5 EOMF encomienda al fiscal instar medidas cautelares y diligencias y, en el proceso de menores, instruir directamente el procedimiento, con facultad de ordenar diligencias a la Policía Judicial.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-837'), 'Art. 3.5 EOMF', 'Intervenir en el proceso penal, instando de la autoridad judicial la adopción de las medidas cautelares que procedan y la práctica de las diligencias encaminadas al esclarecimiento de los hechos o instruyendo directamente el procedimiento en el ámbito de lo dispuesto en la Ley Orgánica reguladora de la Responsabilidad Penal de los Menores, pudiendo ordenar a la Policía Judicial aquellas diligencias que estime oportunas.', null, '3f9179c1e6486583458a0f712a3726e1ba34440787fc6cabfe5705941be1353b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3f9179c1e6486583458a0f712a3726e1ba34440787fc6cabfe5705941be1353b')
  returning id
), o as (
