  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dictar sentencia de conformidad cuando el menor reconozca los hechos.', false), ('B', 'Instruir directamente el procedimiento, pudiendo ordenar a la Policía Judicial las diligencias que estime oportunas.', true), ('C', 'Acordar por sí mismo el internamiento cautelar del menor.', false)) as v(label, body, ok)
)
