with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 520 de la Ley de Enjuiciamiento Criminal, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial, en todo caso, en el plazo máximo de:', 'El art. 520.1 LECrim, como el art. 17.2 CE, limita la detención preventiva al tiempo estrictamente necesario y, en todo caso, a un máximo de setenta y dos horas.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.1 LECRIM', 'La detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos. Dentro de los plazos establecidos en la presente Ley, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.', null, '252abb5a5e7e6053e25cbebfe7340a15a3e975da109f23aa480e307008ad9ea8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '252abb5a5e7e6053e25cbebfe7340a15a3e975da109f23aa480e307008ad9ea8')
  returning id
), o as (
