  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Criminal, el detenido podrá renunciar a la preceptiva asistencia de abogado si su detención lo fuere por hechos susceptibles de ser tipificados exclusivamente como:', 'El art. 520.8 LECrim solo admite la renuncia al abogado en detenciones por hechos tipificables exclusivamente como delitos contra la seguridad del tráfico, previa información clara; la renuncia es revocable en cualquier momento.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.8 LECRIM', 'No obstante, el detenido o preso podrá renunciar a la preceptiva asistencia de abogado si su detención lo fuere por hechos susceptibles de ser tipificados exclusivamente como delitos contra la seguridad del tráfico', null, '4f084179699037eb7ea729b5e32249bf4b25823bd98226b70e4506938d7c81f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4f084179699037eb7ea729b5e32249bf4b25823bd98226b70e4506938d7c81f2')
