with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 520 bis de la Ley de Enjuiciamiento Criminal, la detención de un presunto partícipe de los delitos del artículo 384 bis podrá prolongarse, con autorización judicial, hasta un límite máximo de:', 'El art. 520 bis.1 LECrim permite prolongar la detención otras 48 horas como máximo, si la prórroga se pide motivadamente en las primeras 48 horas y el juez la autoriza en las 24 horas siguientes.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520 bis.1 LECRIM', 'No obstante, podrá prolongarse la detención el tiempo necesario para los fines investigadores, hasta un límite máximo de otras cuarenta y ocho horas, siempre que, solicitada tal prórroga mediante comunicación motivada dentro de las primeras cuarenta y ocho horas desde la detención, sea autorizada por el Juez en las veinticuatro horas siguientes.', null, 'df47fab2ca97d7948a06685ec3f522523cd5836f2ae6d9546b8bed051fa4c340', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'df47fab2ca97d7948a06685ec3f522523cd5836f2ae6d9546b8bed051fa4c340')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Otras cuarenta y ocho horas, siempre que la prórroga se solicite dentro de las primeras cuarenta y ocho horas desde la detención.', true), ('B', 'Otras setenta y dos horas, siempre que la prórroga se solicite dentro de las primeras veinticuatro horas desde la detención.', false), ('C', 'Otras veinticuatro horas, siempre que la prórroga se solicite antes de que transcurran setenta y dos horas desde la detención.', false)) as v(label, body, ok)
)
