with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 284 de la Ley de Enjuiciamiento Criminal, cuando no exista autor conocido del delito, la Policía Judicial conservará el atestado a disposición del Ministerio Fiscal y de la autoridad judicial, sin enviárselo, salvo, entre otros casos, que:', 'El art. 284.2 LECrim obliga a remitir el atestado sin autor conocido en tres casos: delitos contra la vida, integridad física, libertad e indemnidad sexuales o corrupción; diligencias con resultado practicadas pasadas 72 horas desde la apertura; o solicitud del fiscal o del juez.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 284.2 LECRIM', 'No obstante, cuando no exista autor conocido del delito la Policía Judicial conservará el atestado a disposición del Ministerio Fiscal y de la autoridad judicial, sin enviárselo, salvo que concurra alguna de las siguientes circunstancias: a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;', null, '9a1524b8d96dfcfc6642535d10b190abb0bcfb7b0e9bf66486153c7d07b18767', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9a1524b8d96dfcfc6642535d10b190abb0bcfb7b0e9bf66486153c7d07b18767')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se trate de cualquier delito contra el patrimonio cuya cuantía supere los 400 euros.', false), ('B', 'Se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción.', true), ('C', 'Hayan transcurrido veinticuatro horas desde la apertura del atestado, aunque no se haya practicado ninguna diligencia.', false)) as v(label, body, ok)
)
