with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 6/1984, reguladora del procedimiento de habeas corpus, los jueces practicarán las actuaciones y dictarán la resolución que proceda en el plazo de:', 'El art. 7 LOHC fija veinticuatro horas desde el auto de incoación para oír a las partes, practicar las pruebas y resolver.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 7 LOHC', 'En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda.', null, 'fe555c4a1c7a85bda759522502c3b2a0073e27816c904e77ce80fdc90a10f3e6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fe555c4a1c7a85bda759522502c3b2a0073e27816c904e77ce80fdc90a10f3e6')
