with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley Orgánica 6/1984, de habeas corpus, ¿cuál de los siguientes está legitimado para instar el procedimiento?', 'El art. 3 LOHC legitima al privado de libertad y a sus familiares y representantes, al Ministerio Fiscal, al Defensor del Pueblo y al abogado defensor; además, el juez puede iniciarlo de oficio.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 3 LOHC', 'Podrán instar el procedimiento de “Habeas Corpus” que esta ley establece: […] b) El Ministerio Fiscal. c) El Defensor del Pueblo. d) El abogado defensor del privado de libertad.', null, '8a6d6aec66a6b05d9ff74e75184465cc147e7001f0f9b2e2285de57afb5bb96f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8a6d6aec66a6b05d9ff74e75184465cc147e7001f0f9b2e2285de57afb5bb96f')
  returning id
