with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 6/1984, de habeas corpus, si la detención obedece a la aplicación de la ley orgánica que desarrolla los supuestos del artículo 55.2 de la Constitución, el procedimiento deberá seguirse ante:', 'El art. 2 LOHC atribuye la competencia, con carácter general, al Juez de Instrucción del lugar donde se encuentre el detenido, pero en los supuestos del art. 55.2 CE corresponde al Juez Central de Instrucción.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 2 LOHC', 'Si la detención obedece a la aplicación de la ley orgánica que desarrolla los supuestos previstos en el art. 55.2 de la Constitución, el procedimiento deberá seguirse ante el Juez Central de Instrucción correspondiente.', null, '78dad12dc8de708dcf7fbcb8adbbbb33edd11c3247b03fdfd9cfc96fa58bd747', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '78dad12dc8de708dcf7fbcb8adbbbb33edd11c3247b03fdfd9cfc96fa58bd747')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Juez Central de Instrucción correspondiente.', true), ('B', 'El Juez de Instrucción del lugar en que se encuentre la persona privada de libertad.', false), ('C', 'La Sala de lo Penal de la Audiencia Nacional.', false)) as v(label, body, ok)
)
