insert into public.topics (slug, title) values ('pn-21-procesal-penal', 'Tema 21. Derecho Procesal Penal: jurisdicción, denuncia, detención, habeas corpus, Ministerio Fiscal y Policía Judicial') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-21-procesal-penal' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley Orgánica del Poder Judicial, el ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente:', 'El art. 2.1 LOPJ (y el art. 117.3 CE) atribuye la potestad jurisdiccional en exclusiva a los jueces y Tribunales determinados por las leyes y los tratados internacionales.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 2.1 LOPJ', 'El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales.', null, 'ad257eed6064b0df124a426327f584bc9bf54f22f64db396920f25f0b7ee11f3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ad257eed6064b0df124a426327f584bc9bf54f22f64db396920f25f0b7ee11f3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consejo General del Poder Judicial y a los jueces y magistrados.', false), ('B', 'A los jueces, a los Tribunales y al Ministerio Fiscal.', false), ('C', 'A los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 9 de la Ley Orgánica del Poder Judicial, la jurisdicción es:', 'El art. 9.6 LOPJ declara la jurisdicción improrrogable y obliga a apreciar de oficio su falta, con audiencia de las partes y del Ministerio Fiscal.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 9.6 LOPJ', 'La jurisdicción es improrrogable. Los órganos judiciales apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma con audiencia de las partes y del Ministerio Fiscal.', null, 'ff202d3fbc9aa7347c8f9fa4af726aefb42bfb95fb6b46c0fa1c320be2496d7f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ff202d3fbc9aa7347c8f9fa4af726aefb42bfb95fb6b46c0fa1c320be2496d7f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Prorrogable por acuerdo expreso de las partes.', false), ('B', 'Improrrogable, y los órganos judiciales apreciarán de oficio la falta de jurisdicción.', true), ('C', 'Improrrogable, pero la falta de jurisdicción solo puede apreciarse a instancia de parte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 88 de la Ley Orgánica del Poder Judicial, la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal corresponde, con carácter general, a:', 'El art. 88.1.a) LOPJ, en la redacción dada por la LO 1/2025 (Tribunales de Instancia), atribuye a las Secciones de Instrucción y a las Secciones Únicas la instrucción de estas causas, salvo las que correspondan a las Secciones de Violencia sobre la Mujer o de Violencia contra la Infancia y la Adolescencia. También conocen, entre otras materias, de los juicios por delito leve y del habeas corpus.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 88.1 LOPJ', 'Con carácter general, en los Tribunales de Instancia, las Secciones de Instrucción o las Secciones Únicas extenderán su jurisdicción a un partido judicial. Estas Secciones conocerán, en el orden penal: a) De la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal de los Tribunales de Instancia', 'Redacción de la LO 1/2025, de 2 de enero, que sustituye los Juzgados de Instrucción por Secciones de Instrucción de los Tribunales de Instancia (implantación por fases); otras leyes del tema, como la LO 6/1984 de habeas corpus (art. 2) o la LECrim, siguen hablando de «Juez de Instrucción». Comprobar que la terminología encaja con la que use el examen.', '54edc242d9de92f94c5ecb3e31b0777692d42960f5e83c000efbc9cc675defc8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '54edc242d9de92f94c5ecb3e31b0777692d42960f5e83c000efbc9cc675defc8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las Secciones de Instrucción o las Secciones Únicas de los Tribunales de Instancia.', true), ('B', 'Las propias Secciones de lo Penal de los Tribunales de Instancia.', false), ('C', 'Las Salas de lo Civil y Penal de los Tribunales Superiores de Justicia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, ¿qué órgano conoce de la instrucción y enjuiciamiento de las causas contra Diputados y Senadores?', 'El art. 57.1.2.º LOPJ atribuye a la Sala de lo Penal del Tribunal Supremo la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, miembros del Gobierno, Diputados y Senadores, entre otros aforados.', 'pn_21_procesal_penal', (select id from public.topics where slug = 'pn-21-procesal-penal'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 57.1 LOPJ', 'La Sala de lo Penal del Tribunal Supremo conocerá: […] De la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, Presidentes del Congreso y del Senado, Presidente del Tribunal Supremo y del Consejo General del Poder Judicial, Presidente del Tribunal Constitucional, miembros del Gobierno, Diputados y Senadores', null, '46978bb42c70b967cc226d9e1f8552e5059e5712049a620c7a6a7d1cbbc82b2f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '46978bb42c70b967cc226d9e1f8552e5059e5712049a620c7a6a7d1cbbc82b2f')
  returning id
), o as (
