  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Sala de lo Penal de la Audiencia Nacional.', false), ('B', 'La Sala de lo Civil y Penal del Tribunal Superior de Justicia de Madrid.', false), ('C', 'La Sala de lo Penal del Tribunal Supremo.', true)) as v(label, body, ok)
)
