-- Lote pn-22-estatuto-victima-evd-v1 (20 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/2015, de 27 de abril, del Estatuto de la víctima del delito (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-22-estatuto-victima', 'Tema 22. La Ley 4/2015 del Estatuto de la víctima del delito') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-22-estatuto-victima' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley 4/2015, del Estatuto de la víctima del delito, sus disposiciones son aplicables a las víctimas de delitos cometidos en España o que puedan ser perseguidos en España:', 'El art. 1 EVD extiende la ley a todas las víctimas de delitos cometidos o perseguibles en España, sin distinguir por nacionalidad, edad ni situación administrativa.', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 1 EVD', 'Las disposiciones de esta Ley serán aplicables, sin perjuicio de lo dispuesto en el artículo 17, a las víctimas de delitos cometidos en España o que puedan ser perseguidos en España, con independencia de su nacionalidad, de si son mayores o menores de edad o de si disfrutan o no de residencia legal.', null, 'daafd26034675579ac6f8cb85437e54661af1b7597860b148e719977027deca3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'daafd26034675579ac6f8cb85437e54661af1b7597860b148e719977027deca3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que tengan nacionalidad española o de otro Estado miembro de la Unión Europea.', false), ('B', 'Con independencia de su nacionalidad, de si son mayores o menores de edad o de si disfrutan o no de residencia legal.', true), ('C', 'Siempre que sean mayores de edad y residan legalmente en España.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2015, del Estatuto de la víctima del delito, se considera víctima directa a:', 'El art. 2.a) EVD define la víctima directa como persona física que sufre un daño o perjuicio directamente causado por el delito; los familiares de la persona fallecida o desaparecida son víctimas indirectas (art. 2.b).', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 2.a) EVD', 'a) Como víctima directa, a toda persona física que haya sufrido un daño o perjuicio sobre su propia persona o patrimonio, en especial lesiones físicas o psíquicas, daños emocionales o perjuicios económicos directamente causados por la comisión de un delito.', null, '24671da7d2f474ce447f27b2e142a8431b29cf68e0d79d5b7f7791f51cec33da', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '24671da7d2f474ce447f27b2e142a8431b29cf68e0d79d5b7f7791f51cec33da')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Toda persona física que haya sufrido un daño o perjuicio sobre su propia persona o patrimonio directamente causado por la comisión de un delito.', true), ('B', 'Toda persona física o jurídica que haya sufrido cualquier perjuicio derivado de un delito.', false), ('C', 'El cónyuge y los hijos de la persona fallecida a consecuencia de un delito.', false)) as v(label, body, ok)
)
