select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 23 de la Ley 4/2015, en el caso de víctimas de algún delito contra la libertad sexual, las medidas de protección de los párrafos a), b), c) y d) del artículo 25.1:', 'El art. 23.4 EVD impone en todo caso, para las víctimas de delitos contra la libertad sexual, las medidas de las letras a) a d) del art. 25.1 (dependencias adaptadas, profesionales formados, misma persona y, a petición, persona del mismo sexo).', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 23.4 EVD', 'En el caso de víctimas de algún delito contra la libertad sexual se aplicarán en todo caso las medidas expresadas en los párrafos a), b), c) y d) del artículo 25.1.', null, '522c909d65e527faac35f78269319ae86de9bf2b269ed99124b2e643c78ff0ea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '522c909d65e527faac35f78269319ae86de9bf2b269ed99124b2e643c78ff0ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se aplicarán en todo caso.', true), ('B', 'Se aplicarán solo si la víctima lo solicita expresamente.', false), ('C', 'Se aplicarán solo si la víctima es menor de edad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 24 de la Ley 4/2015, durante la fase de investigación del delito, la valoración de las necesidades de la víctima y la determinación de las medidas de protección corresponden:', 'El art. 24.1.a) EVD atribuye la decisión en fase de investigación al Juez de Instrucción o de Violencia sobre la Mujer; el Fiscal y la policía pueden hacer una evaluación y adoptar medidas provisionales. En la fase de enjuiciamiento corresponde al Juez o Tribunal de la causa.', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 24.1 EVD', 'a) Durante la fase de investigación del delito, al Juez de Instrucción o al de Violencia sobre la Mujer, sin perjuicio de la evaluación y resolución provisionales que deberán realizar y adoptar el Fiscal, en sus diligencias de investigación o en los procedimientos sometidos a la Ley Orgánica de Responsabilidad Penal de los Menores, o los funcionarios de policía que actúen en la fase inicial de las investigaciones.', 'El art. 24.1.a) EVD sigue mencionando al «Juez de Instrucción» y al «de Violencia sobre la Mujer»; tras la LO 1/2025 de la LOPJ esos órganos son Secciones de los Tribunales de Instancia. La respuesta es literal de la EVD vigente.', '27eb41238a98e677ae2f1fe3fb3659f20b8d3dce0eee63e37723ba55744e08b8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '27eb41238a98e677ae2f1fe3fb3659f20b8d3dce0eee63e37723ba55744e08b8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivamente a los funcionarios de policía que hayan recibido la denuncia.', false), ('B', 'Al Juez de Instrucción o al de Violencia sobre la Mujer, sin perjuicio de la evaluación y resolución provisionales del Fiscal o de los funcionarios de policía que actúen en la fase inicial.', true), ('C', 'A las Oficinas de Asistencia a las Víctimas, con informe del Ministerio Fiscal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 24 de la Ley 4/2015, respecto de las medidas de protección acordadas conforme a los artículos 25 y 26:', 'El art. 24.2 EVD exige valorar las necesidades manifestadas por la víctima y su voluntad, y le permite renunciar a las medidas de protección acordadas.', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 24.2 EVD', 'La víctima podrá renunciar a las medidas de protección que hubieran sido acordadas de conformidad con los artículos 25 y 26.', null, 'abfddab7ac5af8b79ef48a901cead204c0e563ae8e18936035625dc13d67fd31', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'abfddab7ac5af8b79ef48a901cead204c0e563ae8e18936035625dc13d67fd31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La víctima no podrá renunciar a ellas en ningún caso.', false), ('B', 'La víctima solo podrá renunciar a ellas con autorización del Ministerio Fiscal.', false), ('C', 'La víctima podrá renunciar a ellas.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 25 de la Ley 4/2015, ¿cuál de las siguientes medidas de protección de las víctimas se prevé para la fase de enjuiciamiento?', 'El art. 25.2 EVD prevé para el enjuiciamiento evitar el contacto visual, oír a la víctima sin estar en la sala, evitar preguntas irrelevantes sobre su vida privada y celebrar la vista sin público. Las otras dos opciones son medidas de la fase de investigación (art. 25.1).', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 25.2 EVD', 'Durante la fase de enjuiciamiento podrán ser adoptadas, conforme a lo dispuesto en la Ley de Enjuiciamiento Criminal, las siguientes medidas para la protección de las víctimas: […] d) Celebración de la vista oral sin presencia de público.', null, '7f19765165f2c034759a6585ec48ac82fe618263af28bc3241787bdbc6970dcd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7f19765165f2c034759a6585ec48ac82fe618263af28bc3241787bdbc6970dcd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La celebración de la vista oral sin presencia de público.', true), ('B', 'Que todas las tomas de declaración a una misma víctima las realice la misma persona.', false), ('C', 'Que se reciba declaración a la víctima en dependencias especialmente concebidas o adaptadas a tal fin.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2015, del Estatuto de la víctima del delito, cuando existan dudas sobre la edad de la víctima y no pueda ser determinada con certeza:', 'El art. 26.3 EVD establece la presunción de minoría de edad a los efectos de la ley.', 'pn_22_estatuto_victima', (select id from public.topics where slug = 'pn-22-estatuto-victima'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 26.3 EVD', 'Cuando existan dudas sobre la edad de la víctima y no pueda ser determinada con certeza, se presumirá que se trata de una persona menor de edad, a los efectos de lo dispuesto en esta Ley.', null, '7c2af3840eff9779a1b5132e8a037fa8b6e81d9a91d86f9788afc44cfcc0769d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7c2af3840eff9779a1b5132e8a037fa8b6e81d9a91d86f9788afc44cfcc0769d')
  returning id
), o as (
