with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 39/2006, de promoción de la autonomía personal y atención a las personas en situación de dependencia, el nivel de protección mínimo del Sistema lo establece:', 'El art. 7 de la Ley 39/2006 distingue tres niveles: el mínimo, establecido por la Administración General del Estado; el acordado entre esta y cada Comunidad Autónoma mediante convenios; y el adicional que pueda establecer cada Comunidad Autónoma.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990'), 'Art. 7 LDEP', '1.º El nivel de protección mínimo establecido por la Administración General del Estado en aplicación del', null, '6bb12cbcecc33067a351a6b4a3dd30d6ef178b1de55588940ccfb7d83859fd48', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6bb12cbcecc33067a351a6b4a3dd30d6ef178b1de55588940ccfb7d83859fd48')
  returning id
