  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Administración General del Estado.', true), ('B', 'Cada Comunidad Autónoma.', false), ('C', 'Las Entidades Locales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 39/2006, el Grado III de dependencia se denomina:', 'El art. 26.1 de la Ley 39/2006 clasifica la dependencia en Grado I (moderada), Grado II (severa) y Grado III (gran dependencia).', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990'), 'Art. 26.1 LDEP', 'c) Grado III. Gran dependencia: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria varias veces al día', 'El art. 26 fue modificado por la Ley 4/2026, de 1 de octubre (letra b) del apartado 1 y sustitución de «actividades básicas de la vida diaria» por «actividades de la vida diaria»), y el BOE remite a una disposición transitoria 8 que no figura en el texto consolidado disponible. La denominación de los grados no cambia, pero conviene revisar la redacción vigente.', '74c870a798e06b5466af0f79df7da5026c3f272d2933468759aca6803197931a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '74c870a798e06b5466af0f79df7da5026c3f272d2933468759aca6803197931a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Gran dependencia.', true), ('B', 'Dependencia severa.', false), ('C', 'Dependencia moderada.', false)) as v(label, body, ok)
)
