with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2023, toda persona de nacionalidad española podrá solicitar por sí misma ante el Registro Civil la rectificación de la mención registral relativa al sexo a partir de que sea:', 'El art. 43.1 de la Ley 4/2023 permite la solicitud por sí mismas a las personas mayores de dieciséis años; entre catorce y dieciséis se presenta por sí mismas pero asistidas por sus representantes legales (art. 43.2).', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Art. 43.1 LGTBI', '1. Toda persona de nacionalidad española mayor de dieciséis años podrá solicitar por sí misma ante el Registro Civil la rectificación de la mención registral relativa al sexo.', null, 'f5fe962d0e1912974050bf52aabc68b25e68c6312fbf6ff28e7f87a7b1bc5e3f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f5fe962d0e1912974050bf52aabc68b25e68c6312fbf6ff28e7f87a7b1bc5e3f')
