  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mayor de edad.', false), ('B', 'Mayor de dieciséis años.', true), ('C', 'Mayor de catorce años, sin asistencia de sus representantes legales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
