with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2023, el ejercicio del derecho a la rectificación registral de la mención relativa al sexo:', 'El art. 44.3 de la Ley 4/2023 prohíbe condicionar la rectificación a informes médicos o psicológicos o a modificaciones corporales previas.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Art. 44.3 LGTBI', '3. El ejercicio del derecho a la rectificación registral de la mención relativa al sexo en ningún caso podrá estar condicionado a la previa exhibición de informe médico o psicológico relativo a la disconformidad con el sexo mencionado en la inscripción de nacimiento, ni a la previa modificación de la apariencia o función corporal de la persona a través de procedimientos médicos, quirúrgicos o de otra índole.', null, '1f5b205170b96e311a2c631c7eb22d68d3575fa6e6e19ba1fe451aed32007e65', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1f5b205170b96e311a2c631c7eb22d68d3575fa6e6e19ba1fe451aed32007e65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Requiere la previa exhibición de un informe psicológico sobre la disconformidad con el sexo registrado.', false), ('B', 'Requiere acreditar un tratamiento médico de al menos dos años.', false), ('C', 'En ningún caso podrá estar condicionado a la previa exhibición de informe médico o psicológico ni a la previa modificación de la apariencia o función corporal.', true)) as v(label, body, ok)
)
