  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2023, las personas que hubieran promovido la rectificación de la mención registral relativa al sexo podrán recuperar la mención que figuraba previamente, siguiendo el mismo procedimiento, una vez transcurridos desde la inscripción de la rectificación:', 'El art. 47 de la Ley 4/2023 permite la reversión transcurridos seis meses desde la inscripción de la rectificación en el Registro Civil.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Art. 47 LGTBI', 'Transcurridos seis meses desde la inscripción en el Registro Civil de la rectificación de la mención registral relativa al sexo, las personas que hubieran promovido dicha rectificación podrán recuperar la mención registral del sexo que figuraba previamente a dicha rectificación en el Registro Civil, siguiendo el mismo procedimiento establecido en este Capítulo para la rectificación registral.', null, '77c7b2159691c1c0110345fab7709ff737832675a619bd3d08e2c30895035533', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '77c7b2159691c1c0110345fab7709ff737832675a619bd3d08e2c30895035533')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
