with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2007, para la igualdad efectiva de mujeres y hombres, se considera discriminación directa por razón de sexo:', 'El art. 6.1 de la LO 3/2007 define la discriminación directa; la disposición aparentemente neutra que causa desventaja es la discriminación indirecta (art. 6.2) y el comportamiento de naturaleza sexual es el acoso sexual (art. 7.1).', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 6.1 LOI', '1. Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.', null, '851381416acac87f4d05a06c41a51af3c379b92e53bb35d74eb24f7b75c7346e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '851381416acac87f4d05a06c41a51af3c379b92e53bb35d74eb24f7b75c7346e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro.', false), ('B', 'La situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.', true), ('C', 'Cualquier comportamiento, verbal o físico, de naturaleza sexual que atente contra la dignidad de una persona.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica 3/2007, constituye acoso por razón de sexo:', 'El art. 7.2 de la LO 3/2007 define el acoso por razón de sexo; el comportamiento de naturaleza sexual es el acoso sexual del art. 7.1, que no se limita al centro de trabajo, y ambos se definen «sin perjuicio» del Código Penal.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 7.2 LOI', '2. Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.', null, 'a054c1d72275736c7ef818a22a76ffee70b5bf52cb4796961b2f13fcc49b499b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a054c1d72275736c7ef818a22a76ffee70b5bf52cb4796961b2f13fcc49b499b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cualquier comportamiento, verbal o físico, de naturaleza sexual, siempre que se produzca dentro del centro de trabajo.', false), ('B', 'Únicamente la conducta que esté tipificada como delito en el Código Penal.', false), ('C', 'Cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11 de la Ley Orgánica 3/2007, las medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres (acciones positivas):', 'El art. 11 de la LO 3/2007 exige que las acciones positivas sean temporales (mientras subsista la desigualdad), razonables y proporcionadas, y permite que también las adopten personas físicas y jurídicas privadas (art. 11.2).', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 11.1 LOI', 'Tales medidas, que serán aplicables en tanto subsistan dichas situaciones, habrán de ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso.', null, 'e41b20953b35f137ddb5de8ca44eb8470b64e1d4f37c31fad308543408b4a04d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e41b20953b35f137ddb5de8ca44eb8470b64e1d4f37c31fad308543408b4a04d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Serán aplicables en tanto subsistan dichas situaciones y habrán de ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso.', true), ('B', 'Tendrán carácter permanente, con independencia de que subsistan o no dichas situaciones.', false), ('C', 'Solo pueden ser adoptadas por los Poderes Públicos, nunca por personas físicas o jurídicas privadas.', false)) as v(label, body, ok)
)
