with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2007, el Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en sus organismos públicos lo aprobará el Gobierno:', 'El art. 64 de la LO 3/2007 dispone que el Gobierno aprobará el Plan al inicio de cada legislatura.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 64 LOI', 'El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado y en los organismos públicos vinculados o dependientes de ella.', null, 'fbce199d52d6426178abbadf5288e6a81ca80f36ec331d7355d6277ea44f111d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fbce199d52d6426178abbadf5288e6a81ca80f36ec331d7355d6277ea44f111d')
