with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 64 de la Ley Orgánica 3/2007, el cumplimiento del Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado será evaluado:', 'El art. 64 de la LO 3/2007 establece que el Plan será objeto de negociación con la representación de los empleados públicos y que su cumplimiento será evaluado anualmente por el Consejo de Ministros.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 64 LOI', 'El Plan será objeto de negociación, y en su caso acuerdo, con la representación legal de los empleados públicos en la forma que se determine en la legislación sobre negociación colectiva en la Administración Pública y su cumplimiento será evaluado anualmente por el Consejo de Ministros.', null, '162a260ce4fddf685cbc6858b5ff40d42d64d89ba586e2049d0970c323c65397', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '162a260ce4fddf685cbc6858b5ff40d42d64d89ba586e2049d0970c323c65397')
  returning id
), o as (
