  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Para facilitar el acceso de las empleadas públicas a puestos directivos en la Administración General del Estado, la Ley Orgánica 3/2007 establece que en las convocatorias de los correspondientes cursos de formación se reservará para ellas, al menos:', 'El art. 60.2 de la LO 3/2007 reserva al menos un 40 % de las plazas de esos cursos a las empleadas públicas que reúnan los requisitos.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 60.2 LOI', 'en las convocatorias de los correspondientes cursos de formación se reservará al menos un 40% de las plazas para su adjudicación a aquéllas que reúnan los requisitos establecidos.', null, 'a0b28de6b2e6f39d270b9b5d5d73ab709011cc88ce76110cc167829f01f001ce', false
