with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2007, las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación profesional, especialmente en:', 'El art. 67 de la LO 3/2007 extiende la promoción de la igualdad en las Fuerzas y Cuerpos de Seguridad del Estado al acceso, formación, ascensos, destinos y situaciones administrativas.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 67 LOI', 'Las normas reguladoras de las Fuerzas y Cuerpos de Seguridad del Estado promoverán la igualdad efectiva entre mujeres y hombres, impidiendo cualquier situación de discriminación profesional, especialmente, en el sistema de acceso, formación, ascensos, destinos y situaciones administrativas.', null, '6647010d578b5e8ac8701c935d0bd1f5d93f85fb0bcd6a2a2ec1ee515ab33d9b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6647010d578b5e8ac8701c935d0bd1f5d93f85fb0bcd6a2a2ec1ee515ab33d9b')
