with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Ley Orgánica 1/2004, de Medidas de Protección Integral contra la Violencia de Género, tiene por objeto actuar contra la violencia que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad:', 'El art. 1.1 de la LO 1/2004 incluye a quienes estén o hayan estado ligados a la mujer por relaciones similares de afectividad, aun sin convivencia.', 'pn_23_igualdad', (select id from public.topics where slug = 'pn-23-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.1 LOVG', 'se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.', null, '64a3a2c80db4ac7986e696ba5afb8c0a4c0a6e022707843264210a7d7b74ad06', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '64a3a2c80db4ac7986e696ba5afb8c0a4c0a6e022707843264210a7d7b74ad06')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que exista o haya existido convivencia.', false), ('B', 'Aun sin convivencia.', true), ('C', 'Solo si la relación sigue vigente en el momento de los hechos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
