insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-24-prl-introduccion', 'Tema 24. Introducción a la Prevención de Riesgos Laborales') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-24-prl-introduccion' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, de Prevención de Riesgos Laborales, se entiende por «prevención»:', 'El art. 4.1.º de la Ley 31/1995 define la prevención como el conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa para evitar o disminuir los riesgos; la posibilidad de sufrir un daño es la definición de «riesgo laboral».', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.1.º PRL', '1.º Se entenderá por «prevención» el conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.', null, '52c8da13aec96a28e889acf38438e69c91fcb209950321c8782d643a20bcb475', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '52c8da13aec96a28e889acf38438e69c91fcb209950321c8782d643a20bcb475')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El conjunto de medidas que se adoptan únicamente después de producirse un accidente de trabajo para evitar que se repita.', false), ('B', 'La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.', false), ('C', 'El conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley 31/1995, el «riesgo laboral» es:', 'El art. 4.2.º de la Ley 31/1995 define el riesgo laboral como la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo; el daño ya sufrido es un «daño derivado del trabajo» (art. 4.3.º) y la característica del trabajo es la «condición de trabajo» (art. 4.7.º).', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.2.º PRL', '2.º Se entenderá como «riesgo laboral» la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.', null, '47f117b54071f606d5af6a6935b134e48a2e86632a006fbe9787b8d9b934939c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '47f117b54071f606d5af6a6935b134e48a2e86632a006fbe9787b8d9b934939c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El daño efectivamente sufrido por un trabajador con motivo u ocasión del trabajo.', false), ('B', 'La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.', true), ('C', 'Cualquier característica del trabajo que pueda influir en la generación de daños para la salud.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, para calificar un riesgo desde el punto de vista de su gravedad se valorarán conjuntamente:', 'El art. 4.2.º de la Ley 31/1995 establece que la gravedad de un riesgo se califica valorando conjuntamente la probabilidad de que se produzca el daño y su severidad.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.2.º PRL', 'Para calificar un riesgo desde el punto de vista de su gravedad, se valorarán conjuntamente la probabilidad de que se produzca el daño y la severidad del mismo.', null, '28eedcc53a7b56d45f6a86fa0a32776e3a90b649f6757c3092dd3c7e6a2f02f7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '28eedcc53a7b56d45f6a86fa0a32776e3a90b649f6757c3092dd3c7e6a2f02f7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La probabilidad de que se produzca el daño y la severidad del mismo.', true), ('B', 'La severidad del daño y el número de trabajadores expuestos.', false), ('C', 'La probabilidad de que se produzca el daño y la duración de la exposición.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
