with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley 31/1995, se consideran «daños derivados del trabajo»:', 'El art. 4.3.º de la Ley 31/1995 incluye como daños derivados del trabajo las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo, sin limitarlos a los accidentes en el centro ni a las enfermedades profesionales.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.3.º PRL', '3.º Se considerarán como «daños derivados del trabajo» las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.', null, 'e6962c7cf47cd8fee9283c4f654295d8e61f076dcdc54021d363ad1c9aeb8e7d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e6962c7cf47cd8fee9283c4f654295d8e61f076dcdc54021d363ad1c9aeb8e7d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.', true), ('B', 'Únicamente las lesiones producidas por accidentes ocurridos dentro del centro de trabajo.', false), ('C', 'Solo las enfermedades profesionales reconocidas por la Seguridad Social.', false)) as v(label, body, ok)
)
