with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, se entiende como «riesgo laboral grave e inminente» aquel que:', 'El art. 4.4.º de la Ley 31/1995 exige dos notas: probabilidad racional de que se materialice en un futuro inmediato y posibilidad de daño grave para la salud.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.4.º PRL', '4.º Se entenderá como «riesgo laboral grave e inminente» aquel que resulte probable racionalmente que se materialice en un futuro inmediato y pueda suponer un daño grave para la salud de los trabajadores.', null, 'ac7373c7cbf772732dc99777850d3c607a5f94a49b7b74c39125d55350c6bc31', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ac7373c7cbf772732dc99777850d3c607a5f94a49b7b74c39125d55350c6bc31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ya se haya materializado y haya causado un daño grave a uno o varios trabajadores.', false), ('B', 'Pueda materializarse a medio plazo, aunque el daño que pueda causar sea leve.', false), ('C', 'Resulte probable racionalmente que se materialice en un futuro inmediato y pueda suponer un daño grave para la salud de los trabajadores.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el caso de exposición a agentes susceptibles de causar daños graves a la salud, la Ley 31/1995 considera que existe riesgo grave e inminente cuando sea probable racionalmente que se materialice en un futuro inmediato una exposición a dichos agentes de la que puedan derivarse daños graves:', 'El párrafo segundo del art. 4.4.º de la Ley 31/1995 aclara que, para la exposición a agentes, hay riesgo grave e inminente aunque los daños graves no se manifiesten de forma inmediata.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.4.º PRL', 'En el caso de exposición a agentes susceptibles de causar daños graves a la salud de los trabajadores, se considerará que existe un riesgo grave e inminente cuando sea probable racionalmente que se materialice en un futuro inmediato una exposición a dichos agentes de la que puedan derivarse daños graves para la salud, aun cuando éstos no se manifiesten de forma inmediata.', null, '139f7a111f9a6a686fcfb7281ee688367e6f39bb754b7b5f002a1fab64127f32', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '139f7a111f9a6a686fcfb7281ee688367e6f39bb754b7b5f002a1fab64127f32')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que los daños se manifiesten de forma inmediata.', false), ('B', 'Aun cuando estos no se manifiesten de forma inmediata.', true), ('C', 'Solo si la exposición ha producido ya daños constatados por el servicio de prevención.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, se entiende como «equipo de trabajo»:', 'El art. 4.6.º de la Ley 31/1995 define el equipo de trabajo como cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo; el equipo llevado o sujetado por el trabajador para protegerse es el equipo de protección individual (art. 4.8.º).', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.6.º PRL', '6.º Se entenderá como «equipo de trabajo» cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo.', null, 'ae6657dd8acf967aa97345d41d076a04506ec1bedb66bb0747f0b40ee7625504', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ae6657dd8acf967aa97345d41d076a04506ec1bedb66bb0747f0b40ee7625504')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo.', true), ('B', 'Cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos.', false), ('C', 'El conjunto de trabajadores designados por el empresario para ocuparse de la actividad preventiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley 31/1995, se entiende como «condición de trabajo»:', 'El art. 4.7.º de la Ley 31/1995 define la condición de trabajo como cualquier característica del trabajo con influencia significativa en la generación de riesgos e incluye, entre otras, los locales e instalaciones, los agentes físicos, químicos y biológicos, los procedimientos para su utilización y la organización y ordenación del trabajo.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.7.º PRL', '7.º Se entenderá como «condición de trabajo» cualquier característica del mismo que pueda tener una influencia significativa en la generación de riesgos para la seguridad y la salud del trabajador.', null, 'f23190a30d90c2735a4747613cb5afc15a664e60d3a16cd6b0de90550f7bbb11', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f23190a30d90c2735a4747613cb5afc15a664e60d3a16cd6b0de90550f7bbb11')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente las características de los locales e instalaciones del centro de trabajo.', false), ('B', 'Cualquier característica del mismo que pueda tener una influencia significativa en la generación de riesgos para la seguridad y la salud del trabajador.', true), ('C', 'El conjunto de cláusulas del contrato de trabajo relativas a jornada y retribución.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, el «equipo de protección individual» es cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud en el trabajo:', 'El art. 4.8.º de la Ley 31/1995 incluye expresamente en el concepto de equipo de protección individual cualquier complemento o accesorio destinado a proteger al trabajador.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.8.º PRL', '8.º Se entenderá por «equipo de protección individual» cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud en el trabajo, así como cualquier complemento o accesorio destinado a tal fin.', null, '464cf3aa051aa8164b5cc23f123d95b1af9bf6eeea4dc26e113159b14209eb2c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '464cf3aa051aa8164b5cc23f123d95b1af9bf6eeea4dc26e113159b14209eb2c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Excluidos los complementos y accesorios, que se consideran equipos de trabajo.', false), ('B', 'Siempre que haya sido adquirido por el propio trabajador.', false), ('C', 'Así como cualquier complemento o accesorio destinado a tal fin.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
