  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, se entienden como procesos, actividades, operaciones, equipos o productos «potencialmente peligrosos» aquellos que:', 'El art. 4.5.º de la Ley 31/1995 califica como potencialmente peligrosos los procesos, actividades, operaciones, equipos o productos que originan riesgos en ausencia de medidas preventivas específicas.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.5.º PRL', '5.º Se entenderán como procesos, actividades, operaciones, equipos o productos «potencialmente peligrosos» aquellos que, en ausencia de medidas preventivas específicas, originen riesgos para la seguridad y la salud de los trabajadores que los desarrollan o utilizan.', null, '51c121e89775230ac40ae4f8cfc6d4a3e91c93280d950db819e011a71b167cf6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '51c121e89775230ac40ae4f8cfc6d4a3e91c93280d950db819e011a71b167cf6')
  returning id
