  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Con carácter general, según la Ley 31/1995, la vigilancia periódica del estado de salud de los trabajadores:', 'El art. 22.1 de la Ley 31/1995 configura la vigilancia de la salud como voluntaria, salvo las excepciones tasadas que la propia ley prevé previo informe de los representantes de los trabajadores.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 22.1 PRL', 'Esta vigilancia sólo podrá llevarse a cabo cuando el trabajador preste su consentimiento.', null, '157650015de56edbc7e69e954d436135c9e44d466db23bb2a7cb65ba02a06053', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '157650015de56edbc7e69e954d436135c9e44d466db23bb2a7cb65ba02a06053')
