  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 25 de la Ley 31/1995, los trabajadores especialmente sensibles a determinados riesgos por sus características personales, estado biológico o discapacidad debidamente reconocida:', 'El art. 25.1 de la Ley 31/1995 obliga a proteger específicamente a los trabajadores especialmente sensibles y prohíbe emplearlos en puestos en los que, por esas circunstancias, puedan generar una situación de peligro para sí mismos o para otros.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 25.1 PRL', 'Los trabajadores no serán empleados en aquellos puestos de trabajo en los que, a causa de sus características personales, estado biológico o por su discapacidad física, psíquica o sensorial debidamente reconocida, puedan ellos, los demás trabajadores u otras personas relacionadas con la empresa ponerse en situación de peligro', null, 'af90f6498202c6b2fe1626a260a225d3ebd9acedfc2b3092fefcb52b79b1c518', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'af90f6498202c6b2fe1626a260a225d3ebd9acedfc2b3092fefcb52b79b1c518')
  returning id
), o as (
