with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 39/1997, Reglamento de los Servicios de Prevención, la evaluación de los riesgos laborales es el proceso dirigido a:', 'El art. 3.1 del RD 39/1997 define la evaluación como el proceso dirigido a estimar la magnitud de los riesgos que no hayan podido evitarse, para que el empresario decida sobre la necesidad y el tipo de medidas preventivas.', 'pn_24_prl_introduccion', (select id from public.topics where slug = 'pn-24-prl-introduccion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-1853'), 'Art. 3.1 RSP', '1. La evaluación de los riesgos laborales es el proceso dirigido a estimar la magnitud de aquellos riesgos que no hayan podido evitarse, obteniendo la información necesaria para que el empresario esté en condiciones de tomar una decisión apropiada sobre la necesidad de adoptar medidas preventivas y, en tal caso, sobre el tipo de medidas que deben adoptarse.', null, '9a090f96b761019a5050a65ad469138906eddcd9f991f36fdea6edf97aede94e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9a090f96b761019a5050a65ad469138906eddcd9f991f36fdea6edf97aede94e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Estimar la magnitud de aquellos riesgos que no hayan podido evitarse.', true), ('B', 'Estimar la magnitud de todos los riesgos de la empresa, incluidos los que ya se hayan evitado.', false), ('C', 'Comprobar el estado de salud de los trabajadores mediante reconocimientos médicos periódicos.', false)) as v(label, body, ok)
)
