  select 'Según el artículo 3 de la Ley 31/1995, esta ley y sus normas de desarrollo son de aplicación:', 'El art. 3.1 de la Ley 31/1995 la extiende a las relaciones laborales y a las relaciones administrativas o estatutarias del personal de las Administraciones Públicas, con las peculiaridades previstas.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 3.1 PRL', 'Esta Ley y sus normas de desarrollo serán de aplicación tanto en el ámbito de las relaciones laborales reguladas en el texto refundido de la Ley del Estatuto de los Trabajadores, como en el de las relaciones de carácter administrativo o estatutario del personal al servicio de las Administraciones Públicas', null, '85d4c8fcc06c5743b8069ab8cfd167ed41d08388fc89e800ba45425b33a11c53', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '85d4c8fcc06c5743b8069ab8cfd167ed41d08388fc89e800ba45425b33a11c53')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente a las relaciones laborales reguladas en el Estatuto de los Trabajadores.', false), ('B', 'Únicamente al personal funcionario de las Administraciones Públicas.', false), ('C', 'Tanto a las relaciones laborales como a las relaciones de carácter administrativo o estatutario del personal al servicio de las Administraciones Públicas.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
