with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Respecto de las actividades cuyas particularidades lo impidan en el ámbito de las funciones públicas de policía, seguridad y resguardo aduanero, la Ley 31/1995 establece que:', 'El art. 3.2 de la Ley 31/1995 excluye esas actividades de policía cuyas particularidades lo impidan, pero dispone que la ley inspirará la normativa específica que regule su protección.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 3.2 PRL', '2. La presente Ley no será de aplicación en aquellas actividades cuyas particularidades lo impidan en el ámbito de las funciones públicas de: –Policía, seguridad y resguardo aduanero. […] No obstante, esta Ley inspirará la normativa específica que se dicte para regular la protección de la seguridad y la salud de los trabajadores que prestan sus servicios en las indicadas actividades.', null, '92f445bcc52195e6781b75231c94498aa1d8443f864af562d1e8061a45632c3a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '92f445bcc52195e6781b75231c94498aa1d8443f864af562d1e8061a45632c3a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se aplicará íntegramente y sin adaptación alguna.', false), ('B', 'No será de aplicación, si bien inspirará la normativa específica que se dicte para proteger la seguridad y la salud de esos trabajadores.', true), ('C', 'No será de aplicación ni servirá de referencia para la normativa específica de esas actividades.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
