with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, el deber de protección de los trabajadores frente a los riesgos laborales:', 'El art. 14.1 de la Ley 31/1995 reconoce el derecho de los trabajadores a una protección eficaz, con el correlativo deber del empresario, que es también un deber de las Administraciones públicas respecto de su personal.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 14.1 PRL', 'Este deber de protección constituye, igualmente, un deber de las Administraciones públicas respecto del personal a su servicio.', null, 'fb37f7f72179f83d8c77cae2a694520527a5ba0bacebebf04336137819cf7532', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fb37f7f72179f83d8c77cae2a694520527a5ba0bacebebf04336137819cf7532')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Constituye, igualmente, un deber de las Administraciones públicas respecto del personal a su servicio.', true), ('B', 'Corresponde exclusivamente a los empresarios del sector privado.', false), ('C', 'Recae principalmente sobre los propios trabajadores.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
