with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, en las empresas que cuenten con representantes de los trabajadores, la información sobre riesgos y medidas preventivas:', 'El art. 18.1 de la Ley 31/1995 canaliza la información a través de los representantes, salvo la relativa a los riesgos específicos del puesto o función y sus medidas, que debe darse directamente a cada trabajador.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 18.1 PRL', 'En las empresas que cuenten con representantes de los trabajadores, la información a que se refiere el presente apartado se facilitará por el empresario a los trabajadores a través de dichos representantes; no obstante, deberá informarse directamente a cada trabajador de los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas de protección y prevención aplicables a dichos riesgos.', null, '06c89fae5b3aaa816e07bcd4b22fd04ac23e8f5c90465697794f55c1d00ce957', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '06c89fae5b3aaa816e07bcd4b22fd04ac23e8f5c90465697794f55c1d00ce957')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se facilitará exclusivamente a los representantes, sin que el empresario deba informar individualmente a ningún trabajador.', false), ('B', 'Se facilitará a través de dichos representantes, pero deberá informarse directamente a cada trabajador de los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas aplicables.', true), ('C', 'Se facilitará siempre directamente a cada trabajador, sin intervención de los representantes.', false)) as v(label, body, ok)
)
