with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley 31/1995, la formación de los trabajadores en materia preventiva deberá impartirse:', 'El art. 19.2 de la Ley 31/1995 prevé la formación dentro de la jornada siempre que sea posible (o en otras horas, descontando ese tiempo), por medios propios o concertados, y sin coste para los trabajadores.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 19.2 PRL', 'La formación a que se refiere el apartado anterior deberá impartirse, siempre que sea posible, dentro de la jornada de trabajo o, en su defecto, en otras horas pero con el descuento en aquélla del tiempo invertido en la misma. La formación se podrá impartir por la empresa mediante medios propios o concertándola con servicios ajenos, y su coste no recaerá en ningún caso sobre los trabajadores.', null, '3663b1630f2ad9d883264f345cd33c132d8e95bfcade4d068ae340400857232f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3663b1630f2ad9d883264f345cd33c132d8e95bfcade4d068ae340400857232f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fuera de la jornada de trabajo y a cargo del trabajador.', false), ('B', 'Exclusivamente dentro de la jornada y por medios propios de la empresa, sin posibilidad de concertarla con servicios ajenos.', false), ('C', 'Siempre que sea posible, dentro de la jornada de trabajo o, en su defecto, en otras horas pero con el descuento en aquella del tiempo invertido.', true)) as v(label, body, ok)
)
