  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, cuando el trabajador considere que su actividad entraña un riesgo grave e inminente para su vida o su salud:', 'El art. 21.2 de la Ley 31/1995 reconoce al trabajador el derecho a interrumpir su actividad y abandonar el lugar de trabajo ante un riesgo grave e inminente para su vida o su salud.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 21.2 PRL', '2. De acuerdo con lo previsto en el apartado 1 del artículo 14 de la presente Ley, el trabajador tendrá derecho a interrumpir su actividad y abandonar el lugar de trabajo, en caso necesario, cuando considere que dicha actividad entraña un riesgo grave e inminente para su vida o su salud.', null, '06933f27dc3b32a01c82b409e37d7533e204c3e50d8ef5cbae7708fba72ae9f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '06933f27dc3b32a01c82b409e37d7533e204c3e50d8ef5cbae7708fba72ae9f2')
  returning id
), o as (
