  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando los representantes legales de los trabajadores acuerden la paralización de la actividad por riesgo grave e inminente, el acuerdo se comunicará de inmediato a la empresa y a la autoridad laboral, la cual anulará o ratificará la paralización en el plazo de:', 'El art. 21.3 de la Ley 31/1995 da a la autoridad laboral un plazo de veinticuatro horas para anular o ratificar la paralización acordada por mayoría de los representantes.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 21.3 PRL', 'Tal acuerdo será comunicado de inmediato a la empresa y a la autoridad laboral, la cual, en el plazo de veinticuatro horas, anulará o ratificará la paralización acordada.', null, 'c540b0458ace0e6f0147b8dc447d6c03996c753895b9544017a4ea17c489e8f0', false
