with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 31/1995, ante cualquier situación que, a su juicio, entrañe por motivos razonables un riesgo para la seguridad y la salud de los trabajadores, el trabajador deberá informar de inmediato:', 'El art. 29.2.4.º de la Ley 31/1995 obliga al trabajador a informar de inmediato a su superior jerárquico directo y a los trabajadores designados o, en su caso, al servicio de prevención.', 'pn_25_prl_normativa', (select id from public.topics where slug = 'pn-25-prl-normativa'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 29.2 PRL', '4.º Informar de inmediato a su superior jerárquico directo, y a los trabajadores designados para realizar actividades de protección y de prevención o, en su caso, al servicio de prevención, acerca de cualquier situación que, a su juicio, entrañe, por motivos razonables, un riesgo para la seguridad y la salud de los trabajadores.', null, '016702013d486e70b040041acafc0d040789e840e2b8c4c2ab60ae5b0aed70b6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '016702013d486e70b040041acafc0d040789e840e2b8c4c2ab60ae5b0aed70b6')
