  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 7/2021, el responsable del tratamiento deberá revisar la necesidad de conservar, limitar o suprimir el conjunto de los datos personales contenidos en cada actividad de tratamiento bajo su responsabilidad:', 'El art. 8.2 de la LO 7/2021 impone una revisión como máximo cada tres años, atendiendo a la edad del afectado, el carácter de los datos y la conclusión de la investigación o procedimiento penal.', 'pn_26_proteccion_datos', (select id from public.topics where slug = 'pn-26-proteccion-datos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806'), 'Art. 8.2 LO7_2021', 'El responsable del tratamiento deberá revisar la necesidad de conservar, limitar o suprimir el conjunto de los datos personales contenidos en cada una de las actividades de tratamiento bajo su responsabilidad, como máximo cada tres años', null, '0f930b8374077d2b09edaf304174f77a3697aad5e642747dc3faef7fa1bc986f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0f930b8374077d2b09edaf304174f77a3697aad5e642747dc3faef7fa1bc986f')
