with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2018, de Protección de Datos Personales y garantía de los derechos digitales, el tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea:', 'El art. 7.1 de la LO 3/2018 fija la edad en catorce años; por debajo, el tratamiento basado en el consentimiento exige el del titular de la patria potestad o tutela (art. 7.2).', 'pn_26_proteccion_datos', (select id from public.topics where slug = 'pn-26-proteccion-datos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 7.1 LOPDGDD', '1. El tratamiento de los datos personales de un menor de edad únicamente podrá fundarse en su consentimiento cuando sea mayor de catorce años.', null, '349ddada15aaeb151c045f907a395607c5aefe23f0c8504f0a80d034f8ff1612', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '349ddada15aaeb151c045f907a395607c5aefe23f0c8504f0a80d034f8ff1612')
