with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley Orgánica 3/2018, el derecho fundamental de las personas físicas a la protección de datos personales está amparado por:', 'El art. 1 de la LO 3/2018 vincula el derecho fundamental a la protección de datos con el art. 18.4 CE y lo remite al Reglamento (UE) 2016/679 y a la propia ley orgánica.', 'pn_26_proteccion_datos', (select id from public.topics where slug = 'pn-26-proteccion-datos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 1 LOPDGDD', 'El derecho fundamental de las personas físicas a la protección de datos personales, amparado por el artículo 18.4 de la Constitución, se ejercerá con arreglo a lo establecido en el Reglamento (UE) 2016/679 y en esta ley orgánica.', null, 'ad13ae05db5314ad0bfae867860b7b51581dd7e9f7f72cd888c40006d1235712', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ad13ae05db5314ad0bfae867860b7b51581dd7e9f7f72cd888c40006d1235712')
