with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2018, cuando la persona fallecida hubiese prohibido expresamente el acceso a sus datos personales, dicha prohibición:', 'El art. 3.1 de la LO 3/2018 permite al fallecido prohibir el acceso, la rectificación o la supresión de sus datos, pero la prohibición no alcanza a los datos de carácter patrimonial respecto de los herederos.', 'pn_26_proteccion_datos', (select id from public.topics where slug = 'pn-26-proteccion-datos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 3.1 LOPDGDD', 'Dicha prohibición no afectará al derecho de los herederos a acceder a los datos de carácter patrimonial del causante.', null, '678b7c20b97e1e0e3009591999b8ef9202ba20488a4a9de28798f5ce32594d62', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '678b7c20b97e1e0e3009591999b8ef9202ba20488a4a9de28798f5ce32594d62')
